window.POEM_DB=window.POEM_DB||{};POEM_DB["song_034"]={"n":"司马光","dyn":"宋","poems":[{"t":"光诗首句云饱食复闲眠又成二章 其二 闲眠","f":"五言律诗","c":["秋怀一事无，暑尽昼凉初。","竹户静长闭，藜床安有馀。","逍遥化胡蝶，容易入华胥。","天上多官府，神仙恐不如。"]},{"t":"九日登麻蔺坂","f":"五言绝句","c":["客路逢佳节，无欢更益愁。","前山造云日，登陟不因游。"]},{"t":"二十七日邀子骏尧夫赏西街诸花","f":"七言绝句","c":["今年节物非常晚，春尽西街花尚多。","试问二三真率友，小车篮舁肯重过。"]},{"t":"二十六日作真率会伯康与君从七十八岁安之七十七岁正叔七十四岁不疑七十三岁叔达七十岁光六十五岁合五百一十五岁口号成诗用安之前韵 其二","f":"七言绝句","c":["经春无事连翩醉，彼此往来能几家。","切莫辞斟十分酒，尽从他笑满头花。"]},{"t":"二十六日作真率会伯康与君从七十八岁安之七十七岁正叔七十四岁不疑七十三岁叔达七十岁光六十五岁合五百一十五岁口号成诗用安之前韵 其一","f":"七言绝句","c":["七人五百有馀岁，同醉花前今古稀。","走马斗鸡非我事，纻衣丝发且相晖。"]},{"t":"二月六日初见待漏房前柳色微绿欣然成咏","f":"七言绝句","c":["宫城映出丝丝绿，顿觉皇州春意回。","从此不辞驱瘦马，六街终日踏尘埃。"]},{"t":"二月二十四日馆宿兴宗舍后桃花盛开偶书牖上","f":"五言绝句","c":["金马春寂寂，秾桃随意开。","夕风零落尽，不待主人来。"]},{"t":"十四日小园置茶招宗圣应之皆辞以醉为诗赠之","f":"五言绝句","c":["草树弄春晖，家家倒载归。","谁怜独醒客，日暝掩双扉。"]},{"t":"又七言","f":"七言绝句","c":["闻道山家门镇开，独驱瘦马出尘埃。","白云明月先无约，何事今宵亦此来。"]},{"t":"又即事二章上呈 其一","f":"七言绝句","c":["雨不成游半路归，逢花值柳倍依依。","朝来赖饮三杯酒，醉卧西斋昼掩扉。"]},{"t":"又即事二章上呈 其二","f":"七言绝句","c":["觉后追思气味长，欢情愁绪两俱忘。","近来方得醉中趣，熟寐沈沈是醉乡。"]},{"t":"又和上元日游南园赏梅花","f":"七言绝句","c":["中令园陪丞相游，百分劝酒不须愁。","春风陌上醒归去，只恐更为桃李羞。"]},{"t":"又和游吴氏园二首 其二","f":"七言绝句","c":["名园易主似行邮，美竹高松景自幽。","谁信本来天地物，长为已有固无由。"]},{"t":"又和游吴氏园二首 其一","f":"七言绝句","c":["天气清和无喘牛，花林烂熳竹林幽。","临风高咏足为乐，有勇知方笑仲由。"]},{"t":"又和董氏东园桧屏石床","f":"七言绝句","c":["密叶萧森翠幕纡，暂来犹恨不长居。","脱冠解带坐终日，花落石床春自如。"]},{"t":"又绝句","f":"七言绝句","c":["举首孤轮不似遥，尊前狂气出云霄。","常娥不惜惜丹桂，欲就高枝挂酒瓢。"]},{"t":"又寄","f":"七言绝句","c":["心目悠悠逐去鸿，别来容易四秋风。","莫嗟密密书连纸，万里经年信一通。"]},{"t":"寄题陟屺寺","f":"七言绝句","c":["郑南峰下寺前轩，反景分明见渭川。","为报十年容易别，于今愁悴不如先。"]},{"t":"又赠谓之 其二","f":"五言绝句","c":["篱下多新菊，渊明归思长。","主人方爱客，未得傲羲皇。"]},{"t":"又赠谓之 其三","f":"五言绝句","c":["君念东归日，应须昼绣荣。","当令故关吏，还识弃繻生。"]},{"t":"又赠谓之 其一","f":"五言绝句","c":["文藻兼名理，三吴第一贤。","乡心几千里，飞雁满秋天。"]},{"t":"三月二十五日安之以诗二绝见招作真率会光以无从者不及赴依韵和呈 其二","f":"七言绝句","c":["杯盘丰腆胜陶令，园沼繁华减白家。","惆怅佳辰掩蓬荜，不陪高会赏邻花。"]},{"t":"三月晦日登丰州故城","f":"七言绝句","c":["春尽芜城天一涯，白榆生荚柳生花。","满川战骨知谁罪，深属来人戒覆车。"]},{"t":"上郡南三十里有相思亭在太山之麓二水所交平皋之上往来者徒习其名莫详其义庆历甲申岁余适延安过于其下于时夏虏梗边征戍未息窃感东山采薇之义叙其情而悯其劳因作五诗庶几不违周公之指且以释亭之名尔 其二","f":"五言绝句","c":["偃蹇登脩阪，高侵云日间。","几人征戍客，跋马望家山。"]},{"t":"上郡南三十里有相思亭在太山之麓二水所交平皋之上往来者徒习其名莫详其义庆历甲申岁余适延安过于其下于时夏虏梗边征戍未息窃感东山采薇之义叙其情而悯其劳因作五诗庶几不违周公之指且以释亭之名尔 其一","f":"五言绝句","c":["岭上双流水，犹知会合时。","行人过于此，那得不相思。"]},{"t":"上郡南三十里有相思亭在太山之麓二水所交平皋之上往来者徒习其名莫详其义庆历甲申岁余适延安过于其下于时夏虏梗边征戍未息窃感东山采薇之义叙其情而悯其劳因作五诗庶几不违周公之指且以释亭之名尔 其四","f":"五言绝句","c":["柳似妖饶舞，花如烂漫妆。","那堪陇头水，呜咽断人肠。"]},{"t":"大热","f":"五言绝句","c":["山泽欲焦枯，炎光满太虚。","不知天地外，暑气复何如。"]},{"t":"小诗招僚友晚游后园二首 其二","f":"七言绝句","c":["麦田小雨陇微青，草树欣欣照晚晴。","花下客来醒亦好，犹胜闭户过清明。"]},{"t":"小诗招僚友晚游后园二首 其一","f":"七言绝句","c":["五陵年少竞春晖，肥马银鞍白玉羁。","何似松间煮新茗，更来花底覆残棋。"]},{"t":"山家","f":"五言绝句","c":["林下脱双履，窗边挂幅巾。","闲堂风掩户，断岭月窥人。"]},{"t":"不寐","f":"七言绝句","c":["四远寂然群动收，只馀严鼓度坊楼。","无由更续三更梦，何处飞来一点愁。"]},{"t":"中秋陪张龙图宴射堂初夕阴云酒行顿解喜而成咏","f":"五言绝句","c":["飞盖共徘徊，西园高宴开。","秋云惜明月，留待庾公来。"]},{"t":"六十寄景仁","f":"七言绝句","c":["从来好与天争力，困竭方惭已力微。","见事晚于蘧伯玉，今知五十九年非。"]},{"t":"双井茶寄赠范景仁","f":"七言绝句","c":["春睡无端巧逐人，驱诃不去苦相亲。","欲凭洪井真茶力，试遣刀圭报谷神。"]},{"t":"太博同年叶兄以诗及建茶为贶家有蜀笺二轴辄敢系诗二章献于左右亦投桃报李之意也 其二","f":"七言绝句","c":["西来万里浣花笺，舒卷云霞照手鲜。","书笥久藏无可称，愿投诗客助新编。"]},{"t":"太博同年叶兄以诗及建茶为贶家有蜀笺二轴辄敢系诗二章献于左右亦投桃报李之意也 其一","f":"七言绝句","c":["闽山草木未全春，破颣真茶采撷新。","雅意不忘同臭味，先分畴昔桂堂人。"]},{"t":"归雁","f":"七言绝句","c":["亦知南国稻粱肥，水满春江努力归。","闻道楚人缯缴细，平沙短草尽藏机。"]},{"t":"石阁春望","f":"五言绝句","c":["极目千里外，川原绣画新。","方知平地上，见不尽青春。"]},{"t":"边将 其二","f":"七言绝句","c":["月白星稀霜气多，卷旗束甲涉葱河。","田家不觉官军度，夜半只闻风雨过。"]},{"t":"边将 其一","f":"七言绝句","c":["红旗一簇聚山椒，霁日清风看射雕。","脱帽少年遥稽首，汉家新将霍嫖姚。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其一","f":"七言绝句","c":["平湖漠漠芰荷稠，水国芳春不胜秋。","空有棹歌人不见，晚风一曲去悠悠。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其六","f":"七言绝句","c":["素舸朱篷青竹篙，棹歌风散近还遥。","斜阳借问归何处，家住水村郎姓萧。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其五","f":"七言绝句","c":["清江向晚采莲稀，独倚兰舟久未归。","目断可堪人不至，斜风细雨湿罗衣。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其二","f":"七言绝句","c":["越女行歌纵棹轻，苍茫别浦晚烟凝。","荷花折尽不归去，潋滟扁舟不易胜。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其三","f":"七言绝句","c":["荷底清涟照绮罗，长安公子旧情多。","踌躇不去知君意，重唱吴音白纻歌。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其四","f":"七言绝句","c":["贺监家居逸兴饶，枝分鉴水阔容舠。","穿荷宜去邀渔叟，共醉船头半榼醪。"]},{"t":"龙女祠后塘自生荷花数枝与史诚之更相酬和 其七","f":"七言绝句","c":["别殿无人梨自芳，玉阶朱槛绕金塘。","馆娃寂寞无西子，羞与吴宫竞晓妆。"]},{"t":"兴宗约游会灵久不闻问以诗趣之","f":"七言绝句","c":["胜地何妨行乐频，万双白璧不赊春。","腊醅已老久未压，杨柳青青不待人。"]},{"t":"兴宗许菊久之未得","f":"七言绝句","c":["菊栽许送定如何，庭下不堪秋草多。","九日无花更无酒，便携藜杖直相过。"]},{"t":"再呈宜甫","f":"五言绝句","c":["西家壶已倒，次第向东邻。","朱户如坚闭，黄花恶笑人。"]},{"t":"再和秉国约游石淙","f":"七言绝句","c":["上国分携十五秋，未尝偶坐捧茶瓯。","石淙今会须如约，彼此霜毛各满头。"]},{"t":"华严真师以诗见贶聊成二章纪其趣尚 其二","f":"七言绝句","c":["素发青眸七十馀，未尝游学只安居。","旁无几杖身轻健，应为心闲得自如。"]},{"t":"华严真师以诗见贶聊成二章纪其趣尚 其一","f":"七言绝句","c":["知足随缘处处安，一身温饱不为难。","禅房窄小才容榻，此外从他世界宽。"]},{"t":"同僚有独游东游者小诗寄之 其三","f":"五言绝句","c":["城楼传晚鼓，稍稍讼庭稀。","起拂衣中土，还骑款段归。"]},{"t":"同僚有独游东游者小诗寄之 其二","f":"五言绝句","c":["咫尺东园乐，无如簿领何。","春风连夜恶，闻道落花多。"]},{"t":"同僚有独游东游者小诗寄之 其一","f":"五言绝句","c":["车马东城路，芬芳数里尘。","风光不相待，愁杀未游人。"]},{"t":"夷齐","f":"七言绝句","c":["夷齐双骨已成尘，独有清名日日新。","饿死沟中人不识，可怜今古几何人。"]},{"t":"孙器之奉使淮浙至江为书见寄以诗谢之 其五","f":"五言绝句","c":["沙溆鹤争飞，波光可染衣。","松江异淇水，信美不如归。"]},{"t":"孙器之奉使淮浙至江为书见寄以诗谢之 其四","f":"五言绝句","c":["岫贴晴天阔，舟缘石岸深。","遥知作书处，缆袅绿波心。"]},{"t":"孙器之奉使淮浙至江为书见寄以诗谢之 其三","f":"五言绝句","c":["吴酿木兰春，红鲈白锦鳞。","玉盘聊下箸，初识紫丝莼。"]},{"t":"孙器之奉使淮浙至江为书见寄以诗谢之 其二","f":"五言绝句","c":["晓棹旌旗迥，暮河钲鼓喧。","商船极目避，汉使一何尊。"]},{"t":"孙器之奉使淮浙至江为书见寄以诗谢之 其一","f":"五言绝句","c":["韊矢迎山驿，轺车下帝台。","夜看牛斗分，应有使星来。"]},{"t":"庆历七年祀南郊礼毕贺赦","f":"七言绝句","c":["雷鼓千通破大幽，天开狱钥纵累囚。","驿书散出先飞鸟，一日恩流四百州。"]},{"t":"执酒","f":"七言绝句","c":["执酒劝君君尽之，今朝取醉不当疑。","好风好景心无事，闲利闲名何足知。"]},{"t":"早春 其一","f":"七言绝句","c":["梅梢柳萼未全开，日澹风和春意来。","雨后谁家有桃李，会须多买及时栽。"]},{"t":"早春寄景仁 其二","f":"五言绝句","c":["叠石溪上春，茅茨卜筑新。","前言如不践，山蝉又笑人。"]},{"t":"早春寄景仁 其一","f":"五言绝句","c":["辛夷花烂开，故人殊未来。","愁看柳渐绿，忍更折残梅。"]},{"t":"次前韵二首 其二","f":"七言绝句","c":["南园莫笑独追寻，明日未知晴与阴。","挥手一朝辞逆旅，满堂安用累千金。"]},{"t":"次前韵二首 其一","f":"七言绝句","c":["头白惜春情更深，花间独醉竞分阴。","泉声醒耳自可乐，不用歌抛满袖金。"]},{"t":"次韵和复古春日五绝句 其五","f":"七言绝句","c":["燕拂人衣絮扑头，红英满地绿阴稠。","残春举目多愁思，休上迢迢百尺楼。"]},{"t":"次韵和复古春日五绝句 其三","f":"七言绝句","c":["东城丝网蹴红毬，北里琼楼唱石州。","堪笑迂儒竹斋里，眼昏逼纸看蝇头。"]},{"t":"次韵和复古春日五绝句 其一","f":"七言绝句","c":["雪霜哀鬓拔还生，桃李新园长未成。","五十尚能胜六十，今年又灭去年情。"]},{"t":"次韵和复古春日五绝句 其四","f":"七言绝句","c":["家藏歌吹只西邻，吹落梅花歌落尘。","百叶桃开深院里，输他白发有情人。"]},{"t":"次韵和复古春日五绝句 其二","f":"七言绝句","c":["车如流水马如龙，花市相逢咽不通。","独闭柴荆老春色，任他陌上暮尘红。"]},{"t":"自都往馀杭怀聂之美","f":"五言绝句","c":["阁上新文卷，欲逢知已开。","相思不能已，攲枕梦君来。"]},{"t":"自渑至洛循谷水行百馀里","f":"七言绝句","c":["已烦谷水远相送，更得嵩峰遥见迎。","水碧峰青看未足，却愁前到洛阳城。"]},{"t":"自题写真","f":"七言绝句","c":["黄面霜须细瘦身，从来未识漫相亲。","居然不可市朝住，骨相天生林野人。"]},{"t":"观孙儿戏感怀","f":"七言绝句","c":["我昔垂髫今白头，中间万事水东流。","此心争得还如是，戏走阶前不识愁。"]},{"t":"观江上人壁许道宁画寒林","f":"五言绝句","c":["昔曾驱瘦马，冲雪过荥阳。","不悟当时景，萧然在此堂。"]},{"t":"过故洛阳城 其二","f":"七言绝句","c":["烟愁雨啸奈华生，宫阙簪蕖旧帝京。","若问古今兴废事，请君只看洛阳城。"]},{"t":"过故洛阳城 其一","f":"七言绝句","c":["四合连山缭绕青，三川滉漾素波明。","春风不识兴亡意，草色年年满故城。"]},{"t":"初春登兴国寺塔","f":"七言绝句","c":["雨过风清露气匀，林花变色柳条新。","为君作意登高处，试望皇州表里春。"]},{"t":"初夏独游南园二首 其二","f":"五言绝句","c":["桃李都无日，梧桐半死身。","那堪衰病意，更作独游人。"]},{"t":"初夏独游南园二首 其一","f":"五言绝句","c":["取醉非无酒，忘忧亦有花。","暂来疑是客，归去不成家。"]},{"t":"别用韵","f":"七言绝句","c":["坐中七叟推年纪，比较前人少几多。","花似锦红头雪白，不游不饮欲如何。"]},{"t":"吹箫","f":"五言绝句","c":["古人吹箫者，以和虞韶声。","后世不复贵，给丧仍卖饧。"]},{"t":"呈乐道","f":"七言绝句","c":["欢迎俛仰皆陈迹，薄宦须臾即色空。","试忆昔年双桂会，只如前日梦魂中。"]},{"t":"呈张子贱","f":"七言绝句","c":["近时洛社名真率，箪食壶浆取次游。","试问西来老朝散，可能同志便相收。"]},{"t":"园中书事二绝 其二","f":"五言绝句","c":["坐嗅白莲蕊，卧看青竹枝。","闲斋不成寐，起读圣俞诗。"]},{"t":"寿安杂诗十首 且游","f":"五言绝句","c":["游人恋山水，日晏澹忘归。","但爱云烟好，那知仆马饥。"]},{"t":"寿安杂诗十首 神林谷二首 其二","f":"七言绝句","c":["鸡帻奇峰云外横，青壁千寻不可上。","却羡樵儿轻险峡，腰绳操斧常来往。"]},{"t":"寿安杂诗十首 神林谷二首 其一","f":"七言绝句","c":["石下泉声蔓草深，石上露浓苍藓遍。","山禽惊起飞且鸣，叶坠空林人不见。"]},{"t":"寿安杂诗十首 灵山寺流泉","f":"五言绝句","c":["去寺犹一里，隔林闻水声。","安知客乘兴，山下远相迎。"]},{"t":"寿安杂诗十首 游神林谷寄邵尧夫","f":"七言绝句","c":["山人有山未尝游，俗客远来仍久留。","白云满眼望不见，可惜宜阳一片秋。"]},{"t":"应天院朝拜回呈景仁","f":"七言绝句","c":["鸡鸣上马过河桥，何异东都赴早朝。","红日已高犹熟寝，比君殊未得逍遥。"]},{"t":"花庵二首 其二","f":"五言绝句","c":["谁谓花庵陋，徒为见者嗤。","此中胜广厦，人自不能知。"]},{"t":"花庵二首 其一","f":"五言绝句","c":["谁谓花庵小，才容三两人。","君看宾席上，经月有凝尘。"]},{"t":"花庵诗寄邵尧夫 其二","f":"七言绝句","c":["自然天物胜人为，万叶无风绿四垂。","犹恨簪绅未离俗，荷衣蕙带始相宜。"]},{"t":"贡院中戏从元礼求酒","f":"五言绝句","c":["顾我虚罍耻，知君馀沥多。","庭前有春雪，如此薄寒何。"]},{"t":"走笔和君锡尧夫","f":"七言绝句","c":["先生洛社坐忘机，大尹朝天去佐时。","今日梅花浮别酒，青云早晚重来披。"]},{"t":"邵尧夫许来石阁久待不至","f":"七言绝句","c":["淡日浓云合复开，碧嵩清洛远萦回。","林间高阁望己久，花外小车犹未来。"]},{"t":"闲居","f":"七言绝句","c":["故人通贵绝相过，门外真堪置雀罗。","我已幽慵僮更懒，雨来春草一番多。"]},{"t":"饮吴之才家","f":"七言绝句","c":["京洛相逢设主人，富家鼎食不如贫。","解衣换酒同为乐，知是交情百倍亲。"]},{"t":"鸡","f":"七言绝句","c":["羽短笼深不得飞，久留宁为稻粱肥。","胶胶风雨鸣何苦，满室高眠正掩扉。"]},{"t":"其日雨中闻姚黄开戏成诗二章呈子骏尧夫 其一","f":"七言绝句","c":["谷雨后来花更浓，前时已是玉玲珑。","客来更说姚黄发，只在街西相第东。"]},{"t":"其日雨中闻姚黄开戏成诗二章呈子骏尧夫 其二","f":"七言绝句","c":["小雨留春春未归，好花虽有恐行稀。","劝君披取鱼蓑去，走看姚黄判湿衣。"]},{"t":"和之美舟行杂诗八首 水鸭","f":"五言绝句","c":["缡縰出短蒲，毰毸浴清水。","物忌太鲜明，何妨染泥滓。"]},{"t":"和之美舟行杂诗八首 鱼鹰","f":"五言绝句","c":["翩然下林表，不惮风湍恶。","得隽辄高飞，为君羞击搏。"]},{"t":"和之美舟行杂诗八首 船行遇风","f":"五言绝句","c":["蔡水仅成波，不若江湖浚。","诚无倾侧忧，缆弱终难进。"]},{"t":"和之美舟行杂诗八首 野花","f":"五言绝句","c":["喧喧桃李蹊，何妨笑幽草。","但愿保天真，徐共春风老。"]},{"t":"和之美舟行杂诗八首 罾鱼者","f":"五言绝句","c":["弱筱絓轻丝，尽日寒溪侧。","获少近知无，溪鱼皆尔识。"]},{"t":"和之美讽古 其二","f":"五言绝句","c":["海客久藏机，鸥知人未知。","如何毫末利，管鲍亦相欺。"]},{"t":"和之美讽古 其一","f":"五言绝句","c":["曲逆从汉祖，出奇谁与让。","一朝寄天下，不及王陵戆。"]},{"t":"和之美河洲四诗 其二","f":"五言绝句","c":["杳杳河洲晚，客行殊未返。","目随林鸟还，心共征鸿远。"]},{"t":"和之美河洲四诗 其一","f":"五言绝句","c":["冉冉河洲晓，晴霞登木杪。","稍见水烟开，孤舟天际小。"]},{"t":"和子华过王帅家见梅花盛开呈君实子骏兼简尧夫","f":"七言绝句","c":["去年与客尽清欢，今日重来立马看。","犹是携觞同醉在，只愁风雨横相干。"]},{"t":"和子华游君贶园 其一","f":"七言绝句","c":["甲第朱门久不开，春风潜入发江梅。","今朝丞相双车辙，碾破林间水畔苔。"]},{"t":"和任开叔观福严院旧题名","f":"七言绝句","c":["墨踪尘淡鬓华新，犹喜重来值故人。","二十二年如转目，洛阳不改旧时春。"]},{"t":"和安之今春于郑国相公及光处得缀珠莲各一本植之盆中仲夏始见一花喜而成咏末句云未知先合谢谁家","f":"七言绝句","c":["春冻消时种两芽，南风薰日见孤花。","先开必自陶钧力，且合归功丞相家。"]},{"t":"和尧夫先生相招游夏圃","f":"五言绝句","c":["野迥秋光满，径微朝露寒。","登高与行远，馀力尚桓桓。"]},{"t":"和次道奉慈斋宫见寄","f":"七言绝句","c":["去住邈如霄与尘，依依欲别更相亲。","虽知洛邑饶英俊，莫忘斋庐并直人。"]},{"t":"和君贶老君庙姚黄牡丹","f":"七言绝句","c":["芳菲触目已萧然，独著金衣奉老仙。","若占上春先秀发，千花万卉不成妍。"]},{"t":"和君锡雪后招探春 其一","f":"七言绝句","c":["莫嫌微雪压梅芽，已有归鸿泊浦沙。","天上诏来难久驻，直须早看洛阳花。"]},{"t":"和张伯常贺迁资政","f":"七言律诗","c":["不驾使车开汉关，不栖岩穴鍊金丹。","岂无开径三人友，分著垂緌五寸冠。","坐饱太仓犹自愧，谬跻秘殿益难安。","愿同野老嬉尧壤，长守先生苜蓿盘。"]},{"t":"和张推官同年春阴无绪偶成 其二","f":"七言绝句","c":["薄寒未去腊才过，春色先知在绿波。","不是宿云能作思，大都王粲自情多。"]},{"t":"和张推官同年春阴无绪偶成 其一","f":"七言绝句","c":["澹泊轻云寒不收，未成春雨只添愁。","风烟寂寞几何限，尽入凭高一寸眸。"]},{"t":"和李君锡惠书及诗勉以早归","f":"七言绝句","c":["书意勤渠诗意新，清如白雪暖如春。","西游不尽溪山乐，策马归来就故人。"]},{"t":"和秉国芙蓉五章 其五","f":"七言绝句","c":["但见涉江求水际，岂知胜木采霜中。","微红未肯全衰歇，正似酡颜鹤发翁。"]},{"t":"和秉国芙蓉五章 其四","f":"七言绝句","c":["后时独立诚难事，犹赖阶庭有菊丛。","绰约霜前弄姿态，非如群木万株红。"]},{"t":"和秉国芙蓉五章 其三","f":"七言绝句","c":["平昔低头避桃李，英华今发岁云秋。","盛时已过浑如我，醉舞狂歌插满头。"]},{"t":"和秉国芙蓉五章 其二","f":"七言绝句","c":["北方稀见诚奇物，笔界轻丝指捻红。","楚蜀可怜人不赏，墙根屋角数无穷。"]},{"t":"和秉国芙蓉五章 其一","f":"七言绝句","c":["清晓霜华漫自浓，独凭爱日养残红。","劝君秉烛须勤赏，阊阖难禁一夜风。"]},{"t":"和留守相公寄酒与景仁","f":"七言绝句","c":["想对白衣初满倾，执杯未饮已诗成。","怀贤孤坐悄无语，不是朝来困宿酲。"]},{"t":"和聂之美重游东郡","f":"七言绝句","c":["南湖重过又逢春，官柳虽疏亦解新。","台榭倾攲宾友散，临风愁杀独游人。"]},{"t":"和景仁七十一偶成","f":"七言绝句","c":["心地长闲为己物，年华不住是天时。","当时海上乘槎客，维楫都无任所之。"]},{"t":"和范景仁宿憩鹤寺","f":"七言绝句","c":["回廊复阁势萦纡，四岭中涵一气虚。","最爱欣欣向荣木，每来相见不相疏。"]},{"t":"和景仁游寿安","f":"七言绝句","c":["宜阳城下作游人，都为衣冠不系身。","众窍怒号成地籁，也胜终日在红尘。"]},{"t":"和景文议交绝句","f":"七言绝句","c":["迩来友义渐隳颓，直谅多闻贵不回。","势利相交何足道，已知馀耳愧陈雷。"]},{"t":"和道矩红梨花二首 其二","f":"七言绝句","c":["蜀江新锦濯朝阳，楚国纤腰傅薄妆。","何事白花零落早，同时不改斗芬芳。"]},{"t":"和道矩红梨花二首 其一","f":"七言绝句","c":["繁枝细叶互低昂，香敌酴醾艳海棠。","应为穷边太寥落，并将春色付秾芳。"]},{"t":"和潞公行及白马寺得留守相公书云名园例惜好花以候同赏诗二章 其二","f":"七言绝句","c":["相国东郊迓帝师，油幢交映碧参差。","都人共喜安舆到，正是馀花可惜时。"]},{"t":"和潞公行及白马寺得留守相公书云名园例惜好花以候同赏诗二章 其一","f":"七言绝句","c":["云汉成章湛露晞，都门宴饯羽觞飞。","谢安不复东山去，争似阿衡得谢归。"]},{"t":"和潞公招尧夫不至","f":"七言绝句","c":["东阁樽罍招共饮，后房罗绮约同观。","既无蓟子分身术，须欠车公一座欢。"]},{"t":"和懋贤闻道矩小园置酒助以酒果副之以诗","f":"七言绝句","c":["芙蓉幕下惜馀闲，不使芳华取次残。","珍果醇醪与新句，并将佳味助清欢。"]},{"t":"垂柳","f":"七言绝句","c":["天意清和二月初，春风不动整如梳。","陶潜宅外时无此，想更萧条不易居。"]},{"t":"奉和经略庞龙图延州南城八咏 其一 迎薰亭","f":"五言绝句","c":["华馆压清波，坐待南风至。","须知明牧贤，善达吾君意。"]},{"t":"奉和经略庞龙图延州南城八咏 其五 翠漪亭","f":"五言绝句","c":["雕檐日华动，滉瀁照漪涟。","四月芰荷满，不似在穷边。"]},{"t":"奉和经略庞龙图延州南城八咏 其八 禊堂","f":"五言绝句","c":["箫鼓震阳休，组练照芳洲。","意气坐中客，羞笑山阴游。"]},{"t":"宜甫家有金铃菊客未之识因代菊赠宜甫","f":"五言绝句","c":["主人倦邀客，寂寞委苍苔。","此日开无益，明年不复开。"]},{"t":"放鹦鹉二首 其二","f":"五言绝句","c":["虽道长安乐，争如在陇头。","林间祝圣主，万岁复千秋。"]},{"t":"放鹦鹉二首 其一","f":"五言绝句","c":["野性思归久，笼樊今始开。","虽知主恩厚，何日肯重来。"]},{"t":"昌言见督诗债戏呈绝句","f":"七言绝句","c":["学馁才贫杼轴劳，踰年避债负诗豪。","倒囊不惜偿虚券，未敌琼瑶旧价高。"]},{"t":"昌言有咏石发诗三章模写精楷殆难复加仆虽未睹兹物而已若识之久者辄复强为三诗以继其后非敢庶几肩差适足为前诗之舆台耳 其一","f":"七言绝句","c":["万古风涛浸石岩，老苔垂足细䰐鬖。","传闻海底珠无数，何事从来散不簪。"]},{"t":"昌言有咏石发诗三章模写精楷殆难复加仆虽未睹兹物而已若识之久者辄复强为三诗以继其后非敢庶几肩差适足为前诗之舆台耳 其三","f":"七言绝句","c":["琅菜来从若木边，非膏非沐绿宛延。","玉盘委积羞佳客，不是陶家无馔钱。"]},{"t":"昌言有咏石发诗三章模写精楷殆难复加仆虽未睹兹物而已若识之久者辄复强为三诗以继其后非敢庶几肩差适足为前诗之舆台耳 其二","f":"七言绝句","c":["金阙银城仙客居，欲传消息问麻姑。","蓬莱无物堪为信，剪寄苍龙一握须。"]},{"t":"昌言谪官符离有病鹤折翼舟载以行及还修注始平公以诗问之命光同赋二首 其二","f":"七言绝句","c":["相阁书传紫闼深，破缄先问九皋禽。","不令一物伤天理，仁爱方知真宰心。"]},{"t":"昌言谪官符离有病鹤折翼舟载以行及还修注始平公以诗问之命光同赋二首 其一","f":"七言绝句","c":["曾下青田啄玉苗，泥沙病羽久萧条。","谪仙不欲留尘世，依旧提携上碧霄。"]},{"t":"明日雨止复招子骏尧夫游南园 其二","f":"七言绝句","c":["遥思花寨交横锦，未分春心斗顿灰。","更与二三头白友，试携薄具上高台。"]},{"t":"明日雨止复招子骏尧夫游南园 其一","f":"七言绝句","c":["昨朝洛北阻游陪，惆怅中桥半醉回。","泼火既经寒食雨，解酲须拨冻醪醅。"]},{"t":"昔予尝权宰韦城今重过之二十五年矣慨然有怀","f":"七言绝句","c":["二十五年南北走，遗爱寂然民记否。","昔日婴儿今壮夫，昔日壮夫今老叟。"]},{"t":"武成致斋奉酬吴冲卿寺丞太学宿直见寄二首 其二","f":"七言绝句","c":["雪后馀冰尚缀檐，月华霜气入疏帘。","难堪琼玉惊心骨，坐觉清寒几倍添。"]},{"t":"武成致斋奉酬吴冲卿寺丞太学宿直见寄二首 其一","f":"七言绝句","c":["广文更直太常斋，咫尺无从尽素怀。","不及清风得随意，夜深容易过天街。"]},{"t":"河北道中作 其三","f":"七言绝句","c":["原上累累古冢高，昔时意气尽贤豪。","断碑名姓已磨灭，永日东风吹野蒿。"]},{"t":"河北道中作 其二","f":"七言绝句","c":["河势东回今几年，浓阴满目尽桑田。","川原变化无终极，一气不为常寂然。"]},{"t":"河北道中作 其一","f":"七言绝句","c":["绿柳阴中白浪花，河边日日暗风沙。","解鞍纵马悄无事，隐几看书随处家。"]},{"t":"河边晚望","f":"七言绝句","c":["高浪崩奔捲白沙，悠悠极望入天涯。","谁能脱落尘中意，乘兴东游坐石槎。"]},{"t":"河桥春别","f":"七言绝句","c":["河桥春尽送君归，又惜无欢度此时。","乱花满眼遮人望，不见行尘空酒旗。"]},{"t":"陜城桃李零落已尽硖石山中今方盛开马上口占","f":"七言绝句","c":["西望飞花千树暗，东来芳蕊一番新。","行人不惜泥涂倦，喜见年光两处春。"]},{"t":"前年春与楚正叔同游陟屺寺今兹已复周岁窅然思之","f":"五言绝句","c":["陟屺寺南山，曾陪半日闲。","春来梦携手，宛在白云间。"]},{"t":"居洛初夏作","f":"七言绝句","c":["四月清和雨乍晴，南山当户转分明。","更无柳絮随风起，惟有葵花向日倾。"]},{"t":"待诏 其二","f":"五言绝句","c":["待诏久公车，囊装半已虚。","雄文虽雅丽，未得似相如。"]},{"t":"待诏 其一","f":"五言绝句","c":["京洛风尘里，相逢眼尽青。","故人多密近，谁诵四隅铭。"]},{"t":"春","f":"七言绝句","c":["红桃素李竞年华，周偏长安万万家。","何事青青庭下柏，东风吹尽亦无花。"]},{"t":"春贴子词 太皇太后阁六首 其六","f":"七言绝句","c":["东宫归政五年馀，隐几时观黄老书。","禁闼无为民自化，熙熙不独在春初。"]},{"t":"春贴子词 太皇太后阁六首 其五","f":"七言绝句","c":["冰澌半解波先绿，柳叶未生条已黄。","四海澄清天子孝，朝回日奉万年觞。"]},{"t":"春贴子词 太皇太后阁六首 其三","f":"五言绝句","c":["长乐晓钟残，皇舆入问安。","东风犹料峭，冒絮禦馀寒。"]},{"t":"春贴子词 太皇太后阁六首 其二","f":"五言绝句","c":["种桃临玉井，裁胜刻金花。","借问此何处，昆山王母家。"]},{"t":"春贴子词 太皇太后阁六首 其一","f":"五言绝句","c":["盛德初临震，阳和已动坤。","发生天施大，厚载母仪尊。"]},{"t":"春贴子词 夫人阁四首 其四","f":"七言绝句","c":["圣主终朝勤万几，燕居专事养希夷。","千门永昼春岑寂，不用车前插竹枝。"]},{"t":"春贴子词 夫人阁四首 其三","f":"七言绝句","c":["绮窗绣户又东风，丹掖游陪岁岁同。","但愿太平无限乐，何须三十六离宫。"]},{"t":"春贴子词 夫人阁四首 其二","f":"五言绝句","c":["剪綵催花发，开帘望燕归。","藏阄新过腊，习舞竞裁衣。"]},{"t":"春贴子词 夫人阁四首 其一","f":"五言绝句","c":["壁带非烟润，金铺霁景鲜。","绣功添采缕，和气入繁弦。"]},{"t":"春贴子词 皇太后阁六首 其六","f":"七言绝句","c":["裁缝大练成春服，慈俭由来性所钟。","肯使外家矜侈靡，车如流水马如龙。"]},{"t":"春贴子词 皇太后阁六首 其五","f":"七言绝句","c":["玉漏声残金殿开，乘舆清跸问安来。","尽将草木欣欣意，同与新春入寿杯。"]},{"t":"春贴子词 皇太后阁六首 其四","f":"七言绝句","c":["钗上花开海燕飞，红缯剪萼蜡粘枝。","风前飘荡参差羽，还似瑶箱呈瑞时。"]},{"t":"春贴子词 皇太后阁六首 其二","f":"五言绝句","c":["暖日初添刻，柔风乍袭衣。","弄孙时哺果，观织屡临机。"]},{"t":"春贴子词 皇太后阁六首 其一","f":"五言绝句","c":["母德思齐盛，天心奋豫初。","青晖凝辇路，佳气拥宸居。"]},{"t":"春贴子词 皇后阁五首 其四","f":"七言绝句","c":["宝胜金幡巧斗功，綵花蜡燕飏和风。","玉盘翠苣映红蓼，捧案朝来献两宫。"]},{"t":"春贴子词 皇后阁五首 其三","f":"五言绝句","c":["沟暖冰初断，窗晴雪半消。","馀寒不足畏，涂壁尽芳椒。"]},{"t":"春贴子词 皇后阁五首 其二","f":"五言绝句","c":["樛木犹藏叶，夭桃未作花。","六宫歌逮下，四海咏宜家。"]},{"t":"春贴子词 皇帝阁六首 其五","f":"七言绝句","c":["浮阳满野白溶溶，泽底山椒淑气通。","草木岂能知造化，一华一叶尽天功。"]},{"t":"春贴子词 皇帝阁六首 其四","f":"五言绝句","c":["候雁来归北，寒鱼陟负冰。","相乌风色改，旸谷日华升。"]},{"t":"春贴子词 皇帝阁六首 其三","f":"五言绝句","c":["盛德方迎木，柔风渐布和。","省耕将效驾，击壤已闻歌。"]},{"t":"春贴子词 皇帝阁六首 其二","f":"五言绝句","c":["鸾路迎长日，农祥正晓天。","九垓同燠沐，万物向蕃鲜。"]},{"t":"春贴子词 皇帝阁六首 其一","f":"五言绝句","c":["肇履璿玑历，重飞缇室灰。","寒随土牛尽，暖应斗车回。"]},{"t":"春晓","f":"五言绝句","c":["钟漏初传晓，满窗风雨寒。","东冈行可种，攲枕不成安。"]},{"t":"春游","f":"五言绝句","c":["人物竞纷华，骊驹逐钿车。","此时松与柏，不及道傍花。"]},{"t":"柳枝词十三首 其十三","f":"七言绝句","c":["宣阳门前三月初，家家杨柳绿藏乌。","欢似白花飘荡去，忍能弃掷博山炉。"]},{"t":"柳枝词十三首 其十二","f":"七言绝句","c":["白雪虽然比絮花，艳阳不得共繁华。","为君故入乌衣巷，飞舞风流谢傅家。"]},{"t":"柳枝词十三首 其十一","f":"七言绝句","c":["五柳先生门乍开，宅边植杖久徘徊。","陌头遥认颜光禄，诘旦先乘瘦马来。"]},{"t":"柳枝词十三首 其十","f":"七言绝句","c":["行人白马去遥遥，初上金堤欲过桥。","望尘不见遮人眼，苦怨无情万万条。"]},{"t":"柳枝词十三首 其九","f":"七言绝句","c":["多愁尤是别离深，折条相赠各沾襟。","留住不住居人意，欲去未去行人心。"]},{"t":"柳枝词十三首 其八","f":"七言绝句","c":["新丰道上灞陵头，又送夫君去远游。","借问柳枝能寄否，古今共有几多愁。"]},{"t":"柳枝词十三首 其七","f":"七言绝句","c":["舞腰缤纷长乐东，柳间怅饮送春风。","请君试望邯郸道，青门袅袅彻新丰。"]},{"t":"柳枝词十三首 其六","f":"七言绝句","c":["双双春燕飏云霄，楚国宫深乐事饶。","会待急管繁弦际，试取纤条并舞腰。"]},{"t":"柳枝词十三首 其五","f":"七言绝句","c":["长门宫晓未成妆，结雨萦风蔽琐窗。","莫令透入华梁燕，那堪负汝更双双。"]},{"t":"柳枝词十三首 其四","f":"七言绝句","c":["属车隐隐远如雷，陈后愁眉久不开。","杨花都不知人意，故入长门宫里来。"]},{"t":"柳枝词十三首 其三","f":"七言绝句","c":["君王游豫赏青春，折柳为弮赐侍臣。","莫怪长条低拂地，只缘供扫属车尘。"]},{"t":"柳枝词十三首 其二","f":"七言绝句","c":["依依高树出宫墙，摇曳青丝百尺长。","愿与宣温万年树，年年岁岁奉君王。"]},{"t":"柳枝词十三首 其一","f":"七言绝句","c":["烟满上林春未归，三三两两雪花飞。","柳条别得东皇意，映堤拂水已依依。"]},{"t":"独乐园二首 其二","f":"五言绝句","c":["客到暂冠带，客归还上关。","朱门客如市，岂得似林间。"]},{"t":"独乐园二首 其一","f":"五言绝句","c":["独乐园中客，朝朝常闭门。","端居无一事，今日又黄昏。"]},{"t":"独步至洛滨 其二","f":"七言绝句","c":["草软波清沙径微，手携筇竹著深衣。","白鸥不信忘机久，见我犹穿岸柳飞。"]},{"t":"独步至洛滨 其一","f":"七言绝句","c":["拜表归来抵寺居，解鞍纵马罢传呼。","紫衣金带尽脱去，便是林间一野夫。"]},{"t":"看花四绝句 其一","f":"七言绝句","c":["洛阳相望尽名园，墙外花胜墙里看。","手摘青梅共挼酒，何须一一具杯盘。"]},{"t":"看花四绝句 其二","f":"七言绝句","c":["洛阳相识尽名流，骑马游胜下马游。","乘兴东西无不到，但逢青眼即淹留。"]},{"t":"看花四绝句 其四","f":"七言绝句","c":["南园桃李近方栽，浇水未乾花已开。","山果野蔬随分有，交游不厌但频来。"]},{"t":"看花四绝句 其三","f":"七言绝句","c":["洛阳春日最繁华，红绿阴中十万家。","谁道群花如锦绣，人将锦绣学群花。"]},{"t":"贻夸者","f":"五言绝句","c":["我乐非君乐，君忧非我忧。","蓬蒿与溟渤，终老不同游。"]},{"t":"送伯淳监汝州酒","f":"五言绝句","c":["惟知负米乐，不觉抱关卑。","出处两得意，是非皆自知。"]},{"t":"送酒与邵尧夫因戏之","f":"七言绝句","c":["林下虽无忧可消，许由闻说挂空瓢。","请君呼取孟光饮，共插花枝煮药苗。"]},{"t":"送酒与邵尧夫","f":"七言绝句","c":["红樱零落杏花开，春物相催次第来。","莫作林间独醒客，任从花笑玉山颓。"]},{"t":"送景仁至丁正臣园寄主人","f":"五言绝句","c":["客到暂开扃，春芜生满庭。","主人殊不顾，修竹为谁青。"]},{"t":"重九日忆菊","f":"五言绝句","c":["节物都何晚，佳辰容易过。","黄花不足念，当奈酒杯何。"]},{"t":"闻正叔与客过赵园欢饮戏成小诗","f":"七言绝句","c":["吾庐寂寞类荒村，但有林间鸟雀喧。","不似楚家多乐事，笙歌拾得醉邻园。"]},{"t":"夏日西斋书事","f":"七言绝句","c":["榴花映叶未全开，槐影沉沉雨势来。","小院地偏人不到，满庭鸟迹印苍苔。"]},{"t":"席君从于洛城种金橘今秋始结六实以其四献开府太师招三客以赏之留守相公时赋诗以纪奇事光窃不自揆辄依高韵继成五章 其五","f":"七言绝句","c":["弊居橘亦自南移，爱护栽培费岁时。","前此实成酸苦甚，应由与德不相宜。"]},{"t":"席君从于洛城种金橘今秋始结六实以其四献开府太师招三客以赏之留守相公时赋诗以纪奇事光窃不自揆辄依高韵继成五章 其四","f":"七言绝句","c":["物不须多且赏奇，禦寒相见结庵时。","江南江北徒虚语，尽信前书是不宜。"]},{"t":"席君从于洛城种金橘今秋始结六实以其四献开府太师招三客以赏之留守相公时赋诗以纪奇事光窃不自揆辄依高韵继成五章 其三","f":"七言绝句","c":["君从好事不知疲，种子成株凡几时。","摘献帝师三取二，自尝两颗且随宜。"]},{"t":"席君从于洛城种金橘今秋始结六实以其四献开府太师招三客以赏之留守相公时赋诗以纪奇事光窃不自揆辄依高韵继成五章 其二","f":"七言绝句","c":["圆小香黄珠颗垂，结成洛邑重霜时。","相公和气陶群物，不是寒温变土宜。"]},{"t":"席君从于洛城种金橘今秋始结六实以其四献开府太师招三客以赏之留守相公时赋诗以纪奇事光窃不自揆辄依高韵继成五章 其一","f":"七言绝句","c":["宜春果结洛阳枝，正遇耆明会客时。","更引轻舟倚芦岸，香粳鲜鲙雅相宜。"]},{"t":"效赵学士体成口号十章献开府太师 其八","f":"七言绝句","c":["首夏清和新雨晴，绿莎细软不妨行。","园夫遮道白何事，栀子花开斑笋生。"]},{"t":"效赵学士体成口号十章献开府太师 其九","f":"七言绝句","c":["矮帽长绦紫縠衫，朱门深静似重岩。","莫言永日浑无事，种药移花一一监。"]},{"t":"效赵学士体成口号十章献开府太师 其五","f":"七言绝句","c":["公厨敕许酿芳樽，屡唤宾朋醉后园。","谑浪略无名位间，谁人知道太师尊。"]},{"t":"效赵学士体成口号十章献开府太师 其三","f":"七言绝句","c":["归来甫可及春残，丞相频邀赏牡丹。","远处名园多不到，尊前日献百馀盘。"]},{"t":"效赵学士体成口号十章献开府太师 其四","f":"七言绝句","c":["洛阳风俗重繁华，荷担樵夫亦戴花。","贪看二公同宴会，游人昏黑忘还家。"]},{"t":"效赵学士体成口号十章献开府太师 其二","f":"七言绝句","c":["东郊车马走红尘，城外多于城里人。","谁信今朝还政后，过如前岁下车新。"]},{"t":"效赵学士体成口号十章献开府太师 其十","f":"七言绝句","c":["八十聪明强健身，况从壮岁秉鸿钧。","功名富贵古亦有，无事归来能几人。"]},{"t":"效赵学士体成口号十章献开府太师 其一","f":"七言绝句","c":["都人共喜太师回，比户争迎不得催。","正值土楼滩水浅，大家出手挽船来。"]},{"t":"效赵学士体成口号十章献开府太师 其七","f":"七言绝句","c":["东田小籍选新声，歌吹胡琴色色精。","客少有时全不用，天然水竹湛馀清。"]},{"t":"晓霁","f":"五言绝句","c":["梦觉繁声绝，林光透隙来。","开门惊乌鸟，馀滴堕苍苔。"]},{"t":"留别东郡诸僚友 其一","f":"七言绝句","c":["际日浮空涨海流，虫沙龙蜃各优游。","津涯浩荡虽难测，不见惊澜曾覆舟。"]},{"t":"留别东郡诸僚友 其四","f":"七言绝句","c":["祖帐飘扬堤柳边，北来飞盖复连翩。","追随不忍轻言别，回首城楼没晚烟。"]},{"t":"留别东郡诸僚友 其三","f":"七言绝句","c":["楚国良金百鍊精，深藏求售价连城。","岂徒丰狱吹毛利，兼有秦台照胆明。"]},{"t":"留别东郡诸僚友 其五","f":"七言绝句","c":["空府同来贤大夫，短亭门外即长涂。","不辞烂醉樽前倒，明日此欢重得无。"]},{"t":"留别东郡诸僚友 其二","f":"七言绝句","c":["白璧紫金为世宝，贤愚知贵莫能名。","庙堂祭器杯盘物，随处得之光彩生。"]},{"t":"留客","f":"七言绝句","c":["酒烟漠漠自生春，舞袖飘飖拍拍新。","须信客归丝竹散，清风白月解愁人。"]},{"t":"病酒呈晋州李八丈","f":"七言绝句","c":["身如五岭炎蒸里，心似三江高浪中。","谁道醉乡风土好，舟车常愿不相通。"]},{"t":"秦人","f":"七言绝句","c":["楚旗猎猎盖山红，回首咸阳一炬空。","惆怅秦人虚用意，几年辛苦得山东。"]},{"t":"读颍公清风集 其二","f":"七言绝句","c":["人生百岁隙中光，唯有高名久不忘。","千古但令编简在，清风养物一何长。"]},{"t":"读颍公清风集 其一","f":"七言绝句","c":["伊皋垂训皆王度，周召陈诗尽国风。","非独立言方不朽，相君功业自无穷。"]},{"t":"读颍公清风集 其四","f":"七言绝句","c":["一言华衮足为荣，况托文编久愈明。","邹湛不逢羊叔子，世间何处复知名。"]},{"t":"得菊并诗","f":"七言绝句","c":["黄花小垡和烟斸，野兴萧萧已相逐。","同来更得兼诗句，久立看诗忘栽菊。"]},{"t":"晚行后园见菊戏宜甫","f":"五言绝句","c":["野菊荒无数，班班初见花。","径须求一醉，试遣问东家。"]},{"t":"晚秋洛中思归东园","f":"七言绝句","c":["不利不名空去国，雁飞叶落未归来。","秋风肯待主人至，篱下黄花随意开。"]},{"t":"晚晖亭","f":"七言绝句","c":["俯临城市厌諠哗，回顾园林景更加。","醉立斜阳头似雪，往来误认白公家。"]},{"t":"梅花 其三","f":"五言绝句","c":["驿使何时发，凭君寄一枝。","陇头人不识，空向笛中吹。"]},{"t":"梅花 其二","f":"五言绝句","c":["塞北为君戍，江南是妾家。","遥知关外雪，只似岭头花。"]},{"t":"梅花 其一","f":"五言绝句","c":["从与夫君别，寒花几度春。","坐愁芳树老，况乃鉴中人。"]},{"t":"梦与之美为寒食游","f":"五言绝句","c":["寒食无佳赏，芳菲半已空。","夜来逢胜友，末至负东风。"]},{"t":"深夜","f":"七言绝句","c":["疏星映户月流天，群动收声四寂然。","嗟尔寒蛬怨何事，悲吟彻曙亦无眠。"]},{"t":"野轩","f":"七言绝句","c":["黄鸡白酒田间乐，藜杖葛巾林下风。","更若食芹仍暴背，野怀并在一轩中。"]},{"t":"阏逢敦牂二月十一日与一二僚友游叔礼园亭以诗戏呈","f":"五言绝句","c":["下马久徘徊，林芳殊未开。","春风真有意，须待主翁来。"]},{"t":"喷玉潭","f":"七言绝句","c":["千尺崖头一派清，古今不绝坠峥嵘。","长风卷起散岩壑，此日方知喷玉名。"]},{"t":"寒食游南园独饮","f":"七言绝句","c":["寒食良辰无赏心，杂花烂熳柳成阴。","若非独酌酬佳景，一日风光直万金。"]},{"t":"普明寺荷塘上置酒","f":"七言绝句","c":["菡萏飘零水寂寥，败荷疏柳共萧条。","烟斜雨细愁无限，醇酒千分不易消。"]},{"t":"景仁思归雨未克行以诗留之","f":"五言绝句","c":["嘉客念归程，泥深未可行。","今朝阴又重，春雨亦多情。"]},{"t":"游喷玉潭 其一","f":"五言绝句","c":["惊风动地起，游客望山行。","若待佳辰去，应无好事名。"]},{"t":"游喷玉潭 其二","f":"五言绝句","c":["万木吼穹谷，驽骀屹不前。","犹胜望尘客，伫立九衢边。"]},{"t":"登长安见山楼","f":"五言绝句","c":["到官今十日，才得一朝闲。","岁晚愁云合，登楼不见山。"]},{"t":"集句诗","f":"七言绝句","c":["年去年来来去忙，暂偷闲卧老僧床。","惊回一觉游仙梦，又逐流莺过短墙。"]},{"t":"叠石溪 其二","f":"五言绝句","c":["山鸟劝人饮，山蝉笑我狂。","归时兴未尽，不得看斜阳。"]},{"t":"叠石溪 其一","f":"五言绝句","c":["道傍行采药，石底卧题名。","野老相迎拜，溪童乍见惊。"]},{"t":"感怀","f":"七言绝句","c":["昨日春冰破水边，今朝腊雪坠风前。","岁华过目疾飞鸟，壮志如何不着鞭。"]},{"t":"数日不至后圃今晚偶来芳物都尽率然成诗","f":"五言绝句","c":["烂漫不解赏，飘零空惨悽。","残红正满地，不忍踏芳蹊。"]},{"t":"虞部刘员外约游金明光以贱事失期刘惠诗见嘲以诗四首谢之 其二","f":"七言绝句","c":["绛阙朝归散玉珂，不游不饮奈春何。","皇仁听使欢娱极，白简从君冷峭多。"]},{"t":"虞部刘员外约游金明光以贱事失期刘惠诗见嘲以诗四首谢之 其一","f":"七言绝句","c":["丝管嘈嘈耳不分，绮罗杂踏自成春。","不唯汉帝昆明小，更觉唐家曲水贫。"]},{"t":"虞部刘员外约游金明光以贱事失期刘惠诗见嘲以诗四首谢之 其三","f":"七言绝句","c":["碧柳红桃照眼春，绮肴芳醴集朝绅。","自嫌林野疏顽迹，难预风流席上宾。"]},{"t":"酬王安之谢药栽二章 其二","f":"七言绝句","c":["护根带土我亲移，荷锸汲泉君自种。","悦目宁将恶草殊，扶危或比兼金重。"]},{"t":"酬王安之谢药栽二章 其一","f":"七言绝句","c":["洛人栽花不栽药，吾属好尚何其偏。","服之虽能已百疾，爱闲成僻无由痊。"]},{"t":"酬尧夫招看牡丹 其一","f":"七言绝句","c":["君家牡丹深浅红，二十四枝为一丛。","不唯春光占七八，才华自是诗人雄。"]},{"t":"酬次道板桥晚望见寄","f":"七言绝句","c":["春来曾约醉河桥，深负垂杨千万条。","今日都门相望处，西风乱叶正萧萧。"]},{"t":"静夜","f":"七言绝句","c":["午夜空斋四悄然，清寒透骨不成眠。","秋风故揭疏帘起，正漏月华来枕前。"]},{"t":"潮水 其二","f":"五言绝句","c":["淋淋出海门，百里雪花喷。","坐看东归去，平沙空有痕。"]},{"t":"潮水 其一","f":"五言绝句","c":["平江欲上潮，古木自萧萧。","两岸饶葭苇，寒波浸寂寥。"]},{"t":"醉","f":"七言绝句","c":["厚于太古暖于春，耳目无营见道真。","果使屈原知醉趣，当年不作独醒人。"]},{"t":"鹭鸶","f":"七言绝句","c":["清闲自合无忧累，白发何因更飒然。","遥望孤飞下秋水，雪花一片落晴天。"]},{"t":"丁尚书挽词二首 其二","f":"五言律诗","c":["丹阙晨趋退，萧然忘世荣。","闲斋虚自白，永日澹无营。","脱落簪缨累，沈冥丘壑情。","贪夫诚有激，千载素风清。"]},{"t":"丁尚书挽词二首 其一","f":"五言律诗","c":["凤跸游汾曲，非熊得伟人。","闺台尤显重，训诰愈深淳。","论道参黄阁，横经侍紫宸。","如何天不整，志业未全伸。"]},{"t":"九日怀聂之美 其一","f":"七言律诗","c":["钱唐江里扁舟上，别后篱花几度黄。","忧患萦心何缭绕，风光满目尽凄凉。","谁同凿落杯中酒，独系茱萸肘后囊。","可复无书道情素，云间空有雁南翔。"]},{"t":"九日怀聂之美 其二","f":"七言律诗","c":["太室横山蔽十里，相思空复上高台。","瓮头白酒行当熟，篱下黄花稍复开。","陶令不无同醉兴，孟君况有解嘲才。","欲凭西北高风势，飞度轘辕劝一杯。"]},{"t":"二十八日会不疑家席上纪实","f":"五言律诗","c":["召客客俱来，赏花花正开。","寒暄方得所，风雨不相催。","席上柳飞雪，门前车隐雷。","主人意仍厚，安得不徘徊。"]},{"t":"二月二日太常致斋晨起呈景仁次道二同舍","f":"五言律诗","c":["官舍春萧瑟，朝来尚薄寒。","人虽繁陌上，尘不近门端。","已负踏青约，仍无举白欢。","凭君御沟上，试折柳条看。"]},{"t":"二月三十日与同舍宴李氏园晚归马上赋诗","f":"七言律诗","c":["门前蹀躞金羁满，坐上连翩玉斝飞。","数尺游丝留客醉，一行垂柳送人归。","同邀胜友时难得，重到名园花已稀。","莫惜芳辰剩行乐，无端风雨横相违。"]},{"t":"八月十五日夜陪留守宣徽登西楼值雨待月久不见","f":"五言律诗","c":["经岁侍佳节，无如阴霭何。","果然时雨足，安用月华多。","未免银缸进，空闻玉漏过。","庾公兴不浅，久为驻鸣珂。"]},{"t":"八月五日夜省直","f":"五言律诗","c":["大火已西落，温风犹袭人。","留连惜纨扇，散诞脱纱巾。","蟾影夜色浅，蛩声秋意新。","图书足自适，何物更关身。"]},{"t":"八月七日夜省直苦雨三首 其三","f":"五言律诗","c":["菊蕊如排粟，青青见叶心。","未尝窥白日，何以散黄金。","攲侧疏篱短，绵延蔓草深。","寒蛩尔何与，终夕亦悲吟。"]},{"t":"八月七日夜省直苦雨三首 其二","f":"五言律诗","c":["怅望中秋月，于今已上弦。","明生圭样小，影露桂花偏。","幽思邈难致，浮云去不还。","何当出阴翳，清彻照中天。"]},{"t":"八月七日夜省直苦雨三首 其一","f":"五言律诗","c":["夜色槐阴重，雨声官舍寒。","野农安敢问，环堵未能完。","尽日流云度，何时大块乾。","正愁开霁晚，霜雾满红栏。"]},{"t":"又云新铸釜斛与今太府寺尺及权衡若合符契复次前韵","f":"七言律诗","c":["裁筒累黍久研精，况复新修釜斛成。","岂校忽微争口语，本期淳古变人情。","既言乐律符今尺，但恐箫韶似郑声。","若欲世人俱信服，凤凰再集颍川城。"]},{"t":"又代孙检讨作二首 其二","f":"五言律诗","c":["人为天地客，处世若浮休。","岂有生长在，祗知名可留。","露沾寒草晚，风啸白杨秋。","地下求文友，应从顾陆游。"]},{"t":"又击毬","f":"五言律诗","c":["肃奉乘轺命，仍陪戏马游。","朋分初迥出，势合复相收。","顾盼华星激，萦回紫电流。","良因重嘉好，礼接使臣优。"]},{"t":"又和二月五日夜风雪","f":"五言律诗","c":["春风正豪怒，夜雪复飘扬。","勿使羁愁乱，自知清兴长。","帘疏声淅沥，灯冷晕微茫。","此夕牛衣客，成名不可忘。"]},{"t":"又和六日四老会","f":"五言律诗","c":["萸房迎令节，菊蕊入芳筵。","华烛初长夜，清霜未冷天。","悲风咽横吹，骤雨送繁弦。","聊附邹枚客，敢希园绮贤。"]},{"t":"又和开叔","f":"五言律诗","c":["寒梅犯雪荣，大隐久专名。","异种生江渚，何年到洛城。","色如虚室白，香似主人清。","响使吴儿见，不思菰菜羹。"]},{"t":"又和安国寺及诸园赏牡丹","f":"七言律诗","c":["洛邑牡丹天下最，西南土沃得春多。","一城奇品推安国，四面名园接月波。","山相著书称上药，翰林弄笔作新歌。","人间朱粉无因学，浪把菱花百遍磨。"]},{"t":"又和来韵","f":"七言律诗","c":["年老逢春无用惊，对花弄笔眼犹明。","不嫌贫舍旧来燕，唤起醉眠何处莺。","一仆相随幅巾出，群童聚看小车行。","人间万事都损去，莫遣胸中气不平。"]},{"t":"又和留题定襄驿","f":"五言律诗","c":["按节羊肠阪，褰帷并塞州。","仁风熙爱日，清德凛高秋。","甘泽随征盖，华星近戍楼。","佗年叱驭事，直笔寄歆彪。"]},{"t":"又和雪霁","f":"五言律诗","c":["南宫来几时，挟纩易春衣。","意谓花将晚，何言雪尚飞。","夜声通旅枕，晓色弄晴晖。","继日劳王事，离离雁已归。"]},{"t":"又寄献","f":"五言律诗","c":["承明共直庐，瞬息八年馀。","幸托屏星驾，前迎使者车。","迹虽殊贵贱，心不置亲疏。","青眼披情素，犹如相见初。"]},{"t":"上巳日与太学诸同舍饮王都尉园","f":"五言律诗","c":["冠盖郁相依，名园花未稀。","游丝萦复展，狂絮堕还飞。","积弩遗风陋，兰亭旧俗微。","何如咏沂水，春服舞雩归。"]},{"t":"上元书怀","f":"五言律诗","c":["老去春无味，年年觉病添。","酒因脾积断，灯为目阿嫌。","势位非其好，纷华已久厌。","唯馀读书乐，暖日坐前檐。"]},{"t":"与乐道约会超化寺比至乐道以疾先归涂中有诗见寄","f":"七言律诗","c":["颠毛种种齿浮摇，屈指交游渐寂寥。","时较半朝非是晚，路无数里不为遥。","子猷垂到复归去，安道虽知未易邀。","古寺徘徊久东望，青春云日冷萧萧。"]},{"t":"久雨效乐天体","f":"五言律诗","c":["雨多虽可厌，气凉还可喜。","欲语口慵开，无眠身懒起。","一榻有馀宽，一饭有馀美。","想彼庙堂人，正应忧燮理。"]},{"t":"之美举进士寓京师此诗寄之","f":"五言律诗","c":["结发声华盛，无疑屈未伸。","何妨久垂翅，从此欲惊人。","鹰击天风壮，鹏飞海浪春。","行当解故褐，不惜化京尘。"]},{"t":"子高有徐浩诗碑昌言借摹其文甫及数本石有微衅惧而归之子高答简有碎珊瑚之戏昌言以诗赠子高同舍皆和","f":"七言律诗","c":["徐公精笔老生神，石刻犹能妙夺真。","几为通书翻丧宝，愈令好事惜传人。","锋铓半折犹能健，圭璧微瑕自足珍。","直使尽随如意碎，石家玉树未全贫。"]},{"t":"山中早春","f":"五言律诗","c":["山木欣欣意，春光次第催。","攲巾望归雁，伏槛听新雷。","岩静闻冰折，巢空喜燕来。","涧花从寂寞，亦向草堂开。"]},{"t":"山头春色","f":"五言律诗","c":["天意欲回煦，群生稍郁蒸。","平田犹未遍，绝岭独先升。","翠色添崖柏，寒声折涧冰。","谁为物外友，挈手共同登。"]},{"t":"出塞","f":"五言律诗","c":["边草荒无路，星河秋夜明。","卷旗遮远塞，歇马受降城。","霜重征衣薄，风高战鼓鸣。","将军功未厌，士卒不须生。"]},{"t":"马病","f":"五言律诗","c":["羸病何其久，仁心到栈频。","须怜苜蓿歉，当认主人贫。","客舍同萧索，山程共苦辛。","未能逢伯乐，且可自相亲。"]},{"t":"中秋夕始平公命与考校诸君置酒赋诗","f":"七言律诗","c":["月华秋色雨鲜新，万里澄空不受尘。","兔濯素毛腾浩露，桂飘香实下飞轮。","光侵酒面寒无力，清入诗豪健有神。","坐客何须辞醉倒，相君应不惜车茵。"]},{"t":"书事","f":"五言律诗","c":["志士喜功业，感时心易劳。","蘖栽终栝柏，荒蔓任蓬蒿。","梁竦慵为吏，萧咸耻诣曹。","风霜果不变，会见出云高。"]},{"t":"书楼","f":"五言律诗","c":["使君有书癖，记览浩无涯。","况此孤楼迥，端无外物哗。","横肱攲曲几，搔首落乌纱。","此趣人谁识，长吟窗日斜。"]},{"t":"云际亭","f":"五言律诗","c":["高齐杳冥际，迥与世尘违。","席上山河近，天边桑柘微。","人间已飘洒，栋里始纷霏。","草树收残照，逍遥久未归。"]},{"t":"五哀诗 马伏波","f":"五言律诗","c":["汉令班南海，蛮兵避郁林。","天涯柱分界，徼外贡输金。","坐失奸臣意，谁明报国心。","一棺忠勇骨，漂泊瘴烟深。"]},{"t":"五哀诗 李牧","f":"五言律诗","c":["椎牛飨壮士，拔距养奇材。","虏帐方惊避，秦金已闇来。","旌旗移幕府，荆棘蔓丛台。","部曲依稀在，犹能话郭开。"]},{"t":"五哀诗 屈平","f":"五言律诗","c":["白玉徒为洁，幽兰未谓芳。","穷羞事令尹，疏不忘怀王。","冤骨消寒渚，忠魂失旧乡。","空馀楚辞在，犹与日争光。"]},{"t":"五哀诗 晁大夫","f":"五言律诗","c":["人主恩犹盛，谗夫弄舌端。","旋闻就斧质，不得解衣冠。","反贼齿才冷，谋臣心尽寒。","晁宗噍类尽，汉室泰山安。"]},{"t":"仁宗皇帝挽歌词二首 其二","f":"五言律诗","c":["雾晓铜鱼跃，霜寒阊阖开。","哀声际海发，灵仗拂天来。","别寝严虚位，重阍閟夜台。","柏城空有路，无复属车回。"]},{"t":"仁宗皇帝挽歌词二首 其一","f":"五言律诗","c":["声教万馀里，文明四十春。","茂勋留信史，盛德满生民。","共适禽鱼乐，安知橐籥仁。","百年龙驭远，空复仰威神。"]},{"t":"六月十八日夜大暑","f":"五言律诗","c":["老柳蜩螗噪，荒庭熠耀流。","人情正苦暑，物怎已惊秋。","月下濯寒水，风前梳白头。","如何夜半客，束带谒公侯。"]},{"t":"双竹","f":"五言律诗","c":["双干标枯腹，青青凡几霜。","龙腾双角直，鲸喷两须长。","但欲寻支遁，安能问辟疆。","屡来非别意，未与此君忘。"]},{"t":"太皇太后挽歌词二首 其二","f":"五言律诗","c":["四纪袆衣盛，两朝长乐尊。","九州贡甘旨，万乘问晨昏。","明辟归元子，嘉谋赉孝孙。","群生资后土，难答化光恩。"]},{"t":"太皇太后挽歌词二首 其一","f":"五言律诗","c":["麟阁承家庆，轩星应德晖。","帝猷阴有补，嫔则动无违。","遽就苍梧野，空馀大练衣。","只应彤管在，万古播鸿徽。"]},{"t":"忆庞之道","f":"五言律诗","c":["畴昔两垂髫，知音结久要。","何言半涂别，不待岁寒彫。","幸有才名在，非随气运消。","英灵犹彷佛，宿草已萧萧。"]},{"t":"文太师挽歌三首 其三","f":"五言律诗","c":["夏屋封何处，山田有卧牛。","蟠根走伊水，回首负嵩丘。","忠孝家风备，哀荣礼秩优。","龙鸾舞宸翰，万古照松楸。"]},{"t":"文太师挽歌三首 其二","f":"五言律诗","c":["美化流民物，薰然遗爱多。","栾公当日社，邵父至今歌。","庭有三鳣集，门容驷马过。","欲知馀庆在，公鼎格平和。"]},{"t":"文太师挽歌三首 其一","f":"五言律诗","c":["汾晋地形美，古今多钜贤。","况承勋烈后，宜有庆灵传。","著位登朝古，声华出众先。","起家从此始，圭组遂蝉联。"]},{"t":"田横墓","f":"七言律诗","c":["昔时南面并称孤，今日还为绛灌徒。","忍死祗能添屈辱，偷生不足爱须臾。","一朝从殉倾群客，千古生风激懦夫。","直使强颜臣汉帝，韩彭未必免同诛。"]},{"t":"月下小饮","f":"七言律诗","c":["美景赏心相值难，良宵四座尽儒冠。","月华过冷衣襟润，酒力易消樽俎寒。","自有笑谈供逸气，不须丝竹借馀欢。","坊楼五鼓欲催曙，桂影长先高兴阑。"]},{"t":"王金吾北园","f":"七言律诗","c":["丞相后园天籞邻，年年分借上林春。","目前但识禽鱼乐，门外何妨车马尘。","花蘤祗疑名品尽，图书方验古今贫。","将军朝下无馀事，端为风烟作主人。"]},{"t":"长安送李尧夫同年","f":"七言律诗","c":["昔岁琼林花气曛，今朝长乐柳梢春。","事随流水滔滔度，鬓结繁霜戢戢新。","世路饱谙都是梦，人生可贵莫如身。","会须筑室临清洛，相与携筇戴葛巾。"]},{"t":"风","f":"五言律诗","c":["陇首红旌急，樽前翠幕重。","林端翻远刹，花外转疏钟。","夜寂清机发，春阑别意浓。","如何玉琴韵，并欲在青松。"]},{"t":"风雪数日不见叔度晚约公明共诣之 其一","f":"五言律诗","c":["云雪连朝闇，朋从叹坐违。","临文与谁共，开卷为君稀。","趣扫六花散，聊通一径微。","当携兔园赋，同映读书帏。"]},{"t":"东窗","f":"五言律诗","c":["临风梳短发，萧飒晚凉新。","不识市朝客，何如江海人。","沈吟凭棐几，攲侧带纱巾。","浊世事无尽，东窗聊放神。"]},{"t":"乐","f":"五言律诗","c":["吾心自有乐，世俗岂能知。","不及老莱子，多于荣启期。","缊袍宽称体，脱粟饱随宜。","乘兴辄独往，携筇任所之。"]},{"t":"乐轩","f":"五言律诗","c":["繁弦凝绿水，叠鼓掺渔阳。","风结舞初急，尘飞歌正长。","凫鹥争上下，栋宇为低昂。","太守且安坐，新声未遽央。"]},{"t":"代叔礼作使北诗","f":"五言律诗","c":["人主爱民物，心无彼此情。","约欢同一国，蒙福遍群生。","玉帛遥相望，风波寂不惊。","熙熙南北海，所至尽升平。"]},{"t":"北轩老杏其大十围春色向晚止开一花予悯其憔悴作诗嘲之","f":"五言律诗","c":["春木争秀发，嗟君独不材。","须惭一花少，强逐众芳开。","顽艳人谁采，微香蝶不来。","直为无用物，空尔费栽培。"]},{"t":"北京留守王太师挽歌词二首 其二","f":"五言律诗","c":["昔日程文士，中间侍坐宾。","游陪惭晚辈，待遇过它人。","方叹龙门远，俄惊马鬣新。","西园行乐处，引领但沾巾。"]},{"t":"北京留守王太师挽歌词二首 其一","f":"五言律诗","c":["卢肇时推重，终军众共贤。","何如夺标日，未及弃繻年。","官历清涂遍，名居美事先。","人间福有五，视履岂非全。"]},{"t":"去春与景仁同至河阳谒晦叔馆于府之后园既去晦叔名其馆曰礼贤梦得作诗以纪其事光虽愧其名亦作诗以继之","f":"七言律诗","c":["蓬飞匏系十馀年，并荫华榱出偶然。","郭隗金台虽见礼，华歆龙尾岂能贤。","浮云世味闲先薄，寒柏交情老更坚。","明日河梁即分首，人生乐事信难全。"]},{"t":"古松","f":"五言律诗","c":["摧颓岩壑间，磊落得天顽。","香叶低渐水，馀根倒挂山。","白猿窥子落，黄鹤认巢还。","不久应为石，莓苔旧已班。"]},{"t":"司徒开府韩国富公挽辞四首 其四","f":"五言律诗","c":["杖屦还私第，精诚在本朝。","爱君老不懈，忧国没方昭。","东阁秋牢落，西芒夜寂寥。","只应忠亮志，气运不能消。"]},{"t":"司徒开府韩国富公挽辞四首 其三","f":"五言律诗","c":["大吕功名重，鸿毛轩冕轻。","闲居客愈盛，暂出市皆倾。","溟海涵容大，龙门谒见荣。","谦光俨在目，恸哭望佳城。"]},{"t":"司徒开府韩国富公挽辞四首 其二","f":"五言律诗","c":["松漠骄无信，渔阳广聚兵。","移书侮中国，决意背齐盟。","直气轻轺入，英辞左衽惊。","虏归烽火灭，宇县复升平。"]},{"t":"司徒开府韩国富公挽辞四首 其一","f":"五言律诗","c":["天祐休明祚，时生隽杰臣。","贤科首多士，宰府泽生民。","焕烂三台正，冲融四海春。","欲知甄冶力，试问白头人。"]},{"t":"四月十三日立夏呈安之","f":"五言律诗","c":["留春春不住，昨夜的然归。","欢趣何妨少，闲游勿怪稀。","林莺欣有托，丛蝶怅无依。","窗下忘怀客，高眠正掩扉。"]},{"t":"平日游园常策筇杖秋来发箧复出貂褥二物皆景仁所贶睹物思人斐然成诗","f":"五言律诗","c":["筇杖携已久，貂褥展犹新。","渐染岷山雪，拂除京国尘。","危扶醉归路，稳称病来身。","赖此斋中物，时如见故人。"]},{"t":"归田诗 其一","f":"五言律诗","c":["秋水风波大，嗟嗟未可游。","渔樵自应乐，圭组为谁忧。","直木知先伐，明珠忌暗投。","果然钩可曲，不惜取封侯。"]},{"t":"归田诗 其四","f":"五言律诗","c":["松菊陶潜宅，蓬蒿仲蔚家。","行游筇杖瘦，啸傲幅巾斜。","屋小疏茅覆，门深乱柳遮。","村童迎客至，竹帚扫桃花。"]},{"t":"归田诗 其三","f":"五言律诗","c":["圣哲虽云远，遗文幸未亡。","沈冥观礼乐，彷佛见虞黄。","鸡黍延三径，琴书乐一堂。","逍遥名教内，富贵亦微茫。"]},{"t":"归田诗 其二","f":"五言律诗","c":["绂冕诚虚器，簪裳悉畏途。","触机身未保，好直道先孤。","甔石曾何有，田园浪更无。","可能推两耜，沮溺共为徒。"]},{"t":"正月二十四日夜雪","f":"五言律诗","c":["叠瓦浮轻雪，参差粉画难。","苦欺初变柳，故压未生兰。","夜色微分白，春容不受寒。","即为花卉夺，犹得暂供看。"]},{"t":"汉宫词","f":"五言律诗","c":["苜蓿花犹短，昌蒲叶未齐。","更衣过柏谷，走马宿棠梨。","逆旅聊怀玺，田间共斗鸡。","犹思饮云露，高举出虹蜺。"]},{"t":"玉徽亭","f":"五言律诗","c":["房公昔漂泊，置酒此鸣琴。","人事有忧乐，山光无古今。","风流俱寂寞，结构尚萧森。","松竹含虚籁，犹疑弦上音。"]},{"t":"龙门","f":"五言律诗","c":["石楼临晴空，南眺出千里。","人怜山气佳，予叹禹功美。","想彼未凿时，极目皆洪水。","谁知耕桑民，幸免鲂与鲤。"]},{"t":"仲庶同年兄自成都移长安以诗寄贺","f":"五言律诗","c":["蚕丛龟印解，鹑野隼旟新。","借问锦江乐，何如兴庆春。","骊歌遮去辙，竹马望行尘。","惠政如膏雨，遥知彼此均。"]},{"t":"伏蒙留守相公赐示陪太师潞公东田宴集诗辄敢属和","f":"七言律诗","c":["舞雩新雨浃公田，水满东溪上下天。","行径乍迂初见笋，浮舟正好未生莲。","弦收裂帛胡琴阕，袖结清风楚舞妍。","相国火城光满路，夜归不假玉蟾圆。"]},{"t":"伫月亭","f":"五言律诗","c":["灯火动鱼矶，湖边过鸟稀。","孤蟾久未上，五马不成归。","长啸风生座，高吟露满衣。","闲情无日厌，岸帻对清晖。"]},{"t":"先春亭","f":"五言律诗","c":["园林近铃阁，旦夕被仁风。","自得芳菲早，岂将疏远同。","冰开半塘绿，雨借数枝红。","会待韶光遍，还应到野丛。"]},{"t":"光诗首句云饱食复闲眠又成二章 其一 饱食","f":"五言律诗","c":["钱少何须万，杯多不过三。","龟肠本易足，熊掌讵宜贪。","散步竹斋外，高吟柳径南。","此心无所用，脱粟亦深惭。"]},{"t":"光顷为诸生常受经于钱丈学赋于张丈今乃叨忝同为侍臣蒙钱丈置酒张丈赐诗不胜愧悚之深言志为谢","f":"五言律诗","c":["畴昔胜冠日，曾为绛帐生。","九言闻至教，一顾得虚声。","不意叨严近，于今接老成。","宁须诗酒赐，侍坐导知荣。"]},{"t":"光皇祐二年谒告归乡里至治平二年方得再来怆然感怀诗以纪事","f":"五言律诗","c":["十六载重归，顺涂歌式微。","青松弊庐在，白首故人稀。","外饰服章改，流光颜貌非。","巫咸旧山色，相见尚依依。"]},{"t":"送龚章判官之卫州","f":"五言律诗","c":["几砚昔年游，于今成十秋。","松坚终发石，鱼变即辞流。","近郡无飞檄，清时不借筹。","淇园春竹美，军宴日椎牛。"]},{"t":"再和邵尧夫年老逢春","f":"七言律诗","c":["年老逢春犹解狂，行歌南陌上东冈。","晴云高鸟各自得，白日游丝相与长。","草色无情尽眼绿，花林多思袭人香。","吾侪幸免簪裾累，痛饮闲吟乐未央。"]},{"t":"再和伯常见寄","f":"七言律诗","c":["诛茅宋玉宅边人，知醉宜城几瓮春。","细雨短蓑渔向市，孤村极浦鼓迎神。","遍游七泽身忘倦，更赋千篇意转新。","不必沧浪羡清泚，向来缨上已无尘。"]},{"t":"华清宫","f":"五言律诗","c":["新丰鸡犬稀，蓟北马秋肥。","金殿翠华去，玉阶红叶飞。","荒林上路废，温谷旧流微。","嗟此非人事，何须问是非。"]},{"t":"同次道元日宿尚书省听戒誓寄常州卲不疑","f":"五言律诗","c":["椒花献岁新，瑄玉侍祠频。","此夕同华省，非才愧后尘。","江风迎茜旆，沙雨待朱轮。","不比斋宫冷，端居弃掷春。"]},{"t":"同宋次道陪宴琼林","f":"七言律诗","c":["冠盖连翩数里尘，帝家全借上林春。","鹓行不动烟霞秀，龙角正高雷雨新。","喜气晴曛宫树绿，飞花醉堕玉卮频。","蒲萄卢橘应相识，半是当年举酒人。"]},{"t":"吕宣徽挽歌二首 其二","f":"五言律诗","c":["维岳人皆仰，长城众所依。","远猷方克壮，昭世忽长违。","象设俨如在，英灵窅不归。","唯应令名久，竹素蔼馀辉。"]},{"t":"吕宣徽挽歌二首 其一","f":"五言律诗","c":["奕世台衡贵，盈门绂冕荣。","遐方流惠化，殊俗詟威声。","宥密资忠力，安平寄老成。","遽骑箕尾去，何以慰苍生。"]},{"t":"吕禄庙","f":"五言律诗","c":["赤帝祚四百，徒然诸吕谋。","出游逢友卖，未返见家收。","弊冢昔无记，遗祠今幸留。","士心俱左袒，何怨曲周侯。"]},{"t":"安之令子河阳官舍作蛙乐轩安之有诗寄题辄敢继和","f":"五言律诗","c":["鼓吹娱俗耳，蛙鸣惬雅怀。","最宜凉雨歇，更与晚风偕。","骥子方长骛，云衢偶未谐。","功名当努力，留此遗吾侪。"]},{"t":"安之朝议哀辞二首 其二","f":"五言律诗","c":["乐易春阳暖，孤高秋气清。","老惟知自适，贫不问为生。","京兆开阡贵，延陵题墓荣。","如何帝师笔，纯孝纪名卿。"]},{"t":"安之朝议哀辞二首 其一","f":"五言律诗","c":["场屋推声价，朝绅仰典型。","朱衣老卿列，白首恋亲庭。","舟壑一朝失，泉台万古扃。","音容宛在目，争免净飘零。"]},{"t":"庆文公八十会口号","f":"七言律诗","c":["元勋茂德古无伦，海内高闲第一人。","台席已酬调鼎志，磻溪还作钓鱼身。","师臣首冠三旌贵，岁历行开九十新。","愿过期颐跻上寿，飞觞四十有馀春。"]},{"t":"戏书宋子才止足堂","f":"五言律诗","c":["举世恋荣禄，夜行无乃劳。","独君年未至，止足一何高。","矮制乌纱帽，宽裁白氎袍。","华榱坐终日，闲按紫檀槽。"]},{"t":"戏呈尧夫","f":"五言律诗","c":["近来朝野客，无坐不谈禅。","顾我何为者，逢人独懵然。","羡君诗既好，说佛众谁先。","只恐前身是，东都白乐天。"]},{"t":"早行","f":"五言律诗","c":["寒犬吠柴门，荒鸡鸣远村。","河声空自急，月影不曾浑。","木末星犹白，榛中露已繁。","客心独惆怅，四顾与谁言。"]},{"t":"早春 其二","f":"五言律诗","c":["璿霄转斗车，春意逼梅花。","熟寐侵街鼓，闲情到酒家。","晴阳浮地末，寒色敛天涯。","归雁空馀迹，朝来印浦沙。"]},{"t":"早春寄东郡旧同僚","f":"五言律诗","c":["楼台带馀雪，寒色未全收。","久负入关意，空为同舍羞。","清樽接胜友，飞盖从贤侯。","应恨春来晚，烟林已数游。"]},{"t":"早朝书事","f":"五言律诗","c":["太白明如李，东方三丈高。","晨光孤照阙，雾气湿侵袍。","槐柳经霜惨，骅骝得路豪。","素餐无小补，俛仰愧金鳌。"]},{"t":"资善堂宴饯应诏","f":"五言律诗","c":["士论归清德，皇心重老成。","陈谟侍经席，得谢解尘缨。","坐密金章并，行徐玉醴清。","都门昔供帐，疏傅未为荣。"]},{"t":"次韵和王胜之十二月十五日朝退马上作","f":"七言律诗","c":["瓦沟微白雪光清，阙角初红海日腾。","尘息长街千骑入，鞘鸣深殿六龙升。","云岩有客空回首，圭荜何人尚曲肱。","自笑鲰生章绶缚，不容逃去正如罾。"]},{"t":"次韵和冲卿中秋胧月","f":"七言律诗","c":["岂无锦幄翠帘垂，匝树明灯正赫曦。","共惜月华方满夜，更当秋色中分时。","乌皮几稳风侵鬓，白玉楼高冷透肌。","千里浮云何处断，北来试问雁应知。"]},{"t":"次韵和江邻几九月五日省直","f":"五言律诗","c":["群驺布路歆，瘦马解鞍回。","雨阕虫声乐，秋深菊意催。","图书纷自适，僚友邈谁陪。","何以消寒夜，残醪不满杯。"]},{"t":"次韵谢杜祁公借观五老图","f":"七言律诗","c":["脱遗轩冕就安闲，笑傲丘园纵倒冠。","白发忧民虽种种，丹心许国尚桓桓。","鸿冥得路高难慕，松老无风韵自寒。","闻说优游多唱和，新篇何惜画图看。"]},{"t":"祁国正献公挽歌三首 其三","f":"五言律诗","c":["先子同乌府，知音诚皦然。","脱缞来拜伏，抚首辱哀怜。","迨此泉扃掩，空悲尘网牵。","无由怀酒絮，撇涕望新阡。"]},{"t":"祁国正献公挽歌三首 其二","f":"五言律诗","c":["钧玉吴台旧，诛茅梁苑新。","位登华衮贵，家似布衣贫。","直道高当世，清风遗后人。","千秋寒照目，竹帛不栖尘。"]},{"t":"祁国正献公挽歌三首 其一","f":"五言律诗","c":["舟楫才猷大，冰霜德操坚。","陶钧成茂业，书史乐高年。","瞻望簪绅共，吁嗟馆舍捐。","举时无异论，方信令名全。"]},{"t":"竹坞","f":"五言律诗","c":["二何迹相继，竹坞日阴森。","欲识养民意，先观爱物心。","低垂樽俎冷，密映管弦深。","勿怪湖光少，年来碧影侵。"]},{"t":"自嘲","f":"五言律诗","c":["英名愧终贾，高节谢巢由。","直取云山笑，空为簪组羞。","浮沈乖俗好，隐显拙身谋。","惆怅临清鉴，霜毛不待秋。"]},{"t":"自嘲","f":"五言律诗","c":["盘飧罗新蔬，充腹不求馀。","穷巷昼扃户，闲轩卧读书。","有心齐塞马，无意羡川鱼。","世道方邀逐，如君术已疏。"]},{"t":"致政王侍郎挽歌二首 其二","f":"五言律诗","c":["振鹭辞灵沼，冥鸿翔太虚。","清朝解鸣玉，旧里挂安车。","诗酒江山胜，园林俸禄馀。","所忠今不往，谁奏茂陵书。"]},{"t":"致政王侍郎挽歌二首 其一","f":"五言律诗","c":["弱冠献奇策，居然终贾才。","赋成平乐馆，歌奉柏梁杯。","丽藻留昭世，英游隔夜台。","土中埋美玉，谁见不兴哀。"]},{"t":"西湖","f":"五言律诗","c":["佳丽三吴国，湖光荡日华。","鱼惊动蘋叶，燕喜掠杨花。","云过山腰黑，风驱雨脚斜。","烟波遥尽处，彷佛见渔家。"]},{"t":"西溪公宴 其二","f":"五言律诗","c":["谢守爱山水，军城况不赊。","鱼惊避落叶，鸟倦立浮查。","古柏依冈远，垂杨带岸斜。","秋风吹急管，一曲度荷花。"]},{"t":"西溪公宴 其一","f":"五言律诗","c":["五马非从乐，西城念劝功。","翠帷低映水，红旆不胜风。","叶脱青山静，云归碧落空。","淹留尽佳兴，新月渐朦胧。"]},{"t":"初到洛中书怀","f":"七言律诗","c":["三十馀年西复东，劳生薄宦等飞蓬。","所存旧业惟清白，不负明君有朴忠。","早避喧烦真得策，未逢危辱好收功。","太平触处农桑满，赢取闾阎鹤发翁。"]},{"t":"别一章改韵同五诗呈尧夫","f":"五言律诗","c":["家虽在城阙，萧瑟似山阿。","远去名利窟，自称安乐窝。","云归白石洞，鹤立碧松柯。","得丧非吾事，何须更寤歌。"]},{"t":"别聂之美","f":"五言律诗","c":["客宦常漂泊，离怀徒自劳。","贫无衣换酒，空有涕沾袍。","木叶寒犹在，江湖暮更豪。","行舟远不见，赖有片帆高。"]},{"t":"别韵一首","f":"七言律诗","c":["风日虽寒昼景长，探春远访白莲庄。","岸冰犹在水先绿，柳叶未生条已黄。","老木根侵苔径窄，新梅花入酒卮香。","天真不必人修饰，得趣勿嫌台馆荒。"]},{"t":"君贶环溪","f":"五言律诗","c":["地胜风埃外，门深花竹间。","波光冷于玉，溪势曲如环。","荣路回翔厌，华轩啸咏闲。","堪羞谢太傅，不复到东山。"]},{"t":"吴正肃公挽歌辞三首 其三","f":"五言律诗","c":["念昔少年日，谬登君子堂。","重言何以称，厚德不能忘。","玉麈声容在，泉台岁月长。","凭谁寄清泪，为我洒松冈。"]},{"t":"吴正肃公挽歌辞三首 其二","f":"五言律诗","c":["辞华已独步，政治复无前。","吏不容三穴，民皆戴二天。","于今知和寡，自古愧才偏。","惆怅棠阴下，仁风尚蔼然。"]},{"t":"吴正肃公挽歌辞三首 其一","f":"五言律诗","c":["皇家延茂异，鹗立迥无伦。","高议谁能夺，英才自有真。","骅骝宁受絷，水鉴不栖尘。","试为咨清论，风流第几人。"]},{"t":"宋相国公挽辞二首 其二","f":"五言律诗","c":["邦光华衮襚，家宝素书陈。","东阁簪裾散，西芒宅兆新。","泉台无复晓，柏径不知春。","独有高文在，芬芳继古人。"]},{"t":"宋相国公挽辞二首 其一","f":"五言律诗","c":["仁圣初承绪，敷天吁隽贤。","得人兹最盛，射策独居先。","禁省英声远，岩廊至化宣。","辞荣还故第，三事究高年。"]},{"t":"张元常挽歌二首 其二","f":"五言律诗","c":["秀眉无足验，结轖遽为灾。","乡曲三年别，江山万里回。","林闾飞旐入，书剑逐舟来。","坟草枯还绿，重泉不复开。"]},{"t":"张元常挽歌二首 其一","f":"五言律诗","c":["为吏文无害，临民政不苛。","浑金生自美，古井澹无波。","方喜风鹏举，旋闻隙驷过。","善人宜寿考，报施定如何。"]},{"t":"李花","f":"五言律诗","c":["嘉李繁相倚，园林淡泊春。","齐纨剪衣薄，吴纻下机新。","色与晴光乱，香和露气匀。","望中皆玉树，环堵不为贫。"]},{"t":"杏解嘲","f":"五言律诗","c":["造物本非我，荣枯那足言。","但馀良干在，何必艳花繁。","壮丽华林苑，欢娱梓泽园。","芳菲如可采，岂得侍君轩。"]},{"t":"沉阴欲雪与同列会饮南斋","f":"五言律诗","c":["簿领日沈迷，从容乐事稀。","宾朋幸相值，樽酒不须违。","惨澹愁云积，参差远树微。","淹留勿轻散，待取雪花飞。"]},{"t":"花庵多牵牛清晨始开日出已瘁花虽甚美而不堪留赏","f":"五言律诗","c":["望远云凝岫，妆馀黛散钿。","缥囊承晓露，翠盖拂秋烟。","响慕非葵比，彫零在槿先。","才供少顷玩，空废日高眠。"]},{"t":"花庵独坐","f":"五言律诗","c":["荒园才一亩，意足已为多。","虽不居丘壑，常如隐薜萝。","忘机林鸟下，极目塞鸿过。","为问市朝客，红尘深几何。"]},{"t":"苏才翁子美有赠扶沟白鹤观黄道士诗纪于屋壁岁久漫灭今县宰周同年得完本于民间抵予求诗","f":"七言律诗","c":["潦倒黄冠无足论，白头嗜酒住荒村。","狂名偶为留诗著，陈迹仍因好事存。","金石锵洋虚殿寂，龙蛇洒落古墙昏。","飞黄灭没浮云外，疲马何能望骏奔。"]},{"t":"运使虞部按行洛西诸县因游所过名山有诗百馀首合为一编蒙赐宠示俾之继作一首","f":"五言律诗","c":["属城穷僻地，揽辔遍周流。","弊政已更化，名山不废游。","鸣驺留谷口，轻屐历岩幽。","聚看官仪者，相扶半白头。"]},{"t":"还陈殿丞原人论","f":"七言律诗","c":["品物芸芸游太虚，不知谁氏宰洪炉。","一株花落分荣辱，万窍风号见有无。","觉后共占犹是梦，衣中所得亦非珠。","何如鼓瑟浴沂水，春服成时咏舞雩。"]},{"t":"还张景昱景昌秀才兄弟诗卷","f":"五言律诗","c":["韡韡新诗卷，青春映棣华。","机云今继美，载协旧承家。","幸托仁人里，时回长者车。","白虹光乱眼，何敢议瑜瑕。"]},{"t":"邵尧夫先生哀辞二首 其二","f":"五言律诗","c":["慕德闻风久，论交倾盖新。","何须半面旧，不待一言亲。","讲道切磋直，忘怀笑语真。","重言蒙蹠实，佩服敢书绅。"]},{"t":"邵尧夫先生哀辞二首 其一","f":"五言律诗","c":["菽藿一箪乐，蒿莱三亩宽。","蒲轮不能起，瓮牖有馀安。","高节去圭角，久要敦岁寒。","今朝郊外客，谁免涕汍澜。"]},{"t":"闰正月十五日夜监直对月怀诸同舍 其二","f":"五言律诗","c":["澹薄春云散，低昂北斗横。","微分汉津雁，静识建章更。","浊酒怜虚爵，高文忆友生。","前轩空不掩，怅息负孤清。"]},{"t":"闲中有富贵","f":"五言律诗","c":["闲中有富贵，迥与俗尘殊。","水净齐纨展，花繁蜀锦纡。","竹风寒扣玉，荷雨急跳珠。","可笑公孙衍，酣歌誇丈夫。"]},{"t":"闲来","f":"五言律诗","c":["闲来观万物，在处可逍遥。","鱼为贪钩得，蛾因赴火焦。","碧梧饥鸑鷟，白粒饱鹪鹩。","带索谁家子，行歌复采樵。"]},{"t":"闲居呈复古","f":"五言律诗","c":["闲居虽懒放，未得便无营。","伐木添山色，穿渠擘水声。","经霜收芋美，带雨接花成。","前日邻翁至，柴门扫叶迎。"]},{"t":"依前韵奉送才元和甫使北","f":"五言律诗","c":["析木带天津，华星随去人。","扬旌踰绝漠，负弩候前尘。","出塞风霜苦，归涂杨柳春。","会书专对美，烨烨满秋筠。"]},{"t":"依韵和仲庶省壁画山水","f":"七言律诗","c":["画工执笔已心游，稍稍蘅皋引杜洲。","堆案烦文犹倦暑，满轩新意忽惊秋。","天生贤者非无谓，官遇明时未易休。","正恐怒飞朝暮事，丹青难得久淹留。"]},{"t":"其夕宿独乐园诘朝将归赋诗","f":"七言律诗","c":["平晓何人汲井华，辘轳声急散春鸦。","开园更有四五日，映叶尚馀三两花。","宿病岑岑犹带酒，无眠耿耿不禁茶。","自嫌行乐妨年少，遽索蓝舆且向家。"]},{"t":"到任明年旨罢官有作","f":"五言律诗","c":["恬然如一梦，分竹守长安。","去日冰犹壮，归时花未阑。","风光经目少，惠爱及民难。","可惜终南色，临行子细看。"]},{"t":"到并州已复数月率尔成诗","f":"五言律诗","c":["忽忽此何地，经时更自猜。","深疑醉里得，复似梦中来。","薄宦真何益，浮生信可咍。","鹏蜩定有分，不若寸心灰。"]},{"t":"和子华应天院行香归过洛川","f":"七言律诗","c":["印节传呼洛北还，府庭无讼不妨闲。","度桥寒色侵春服，按辔晴光露晓山。","香穗徘徊凝广殿，花篮繁会满通阛。","自知白雪高难和，忍愧谁能寄我颜。"]},{"t":"和子华招潞公暑饮","f":"七言律诗","c":["朱门近在府园东，杖屦过从跬步中。","避暑连翩投辖宴，析酲萧洒满襟风。","闲来高韵浑如鹤，醉里朱颜却变童。","剪烛添香欢未极，但惊铜漏太匆匆。"]},{"t":"和子骏约游一二园亭看花遇雨而止","f":"五言律诗","c":["行乐及佳时，官闲无所羁。","只知花正发，不共雨为期。","浅草碧无际，浓云冷四垂。","陪游兴未尽，安得不相思。"]},{"t":"和子骏洛中书事","f":"七言律诗","c":["西都自古繁华地，冠盖优游萃五方。","比户清风人种竹，满川浓绿土宜桑。","凿龙山断开天阙，导洛波回载羽觞。","况有耆英诗酒乐，问君何处不如唐。"]},{"t":"和子骏新荷","f":"五言律诗","c":["懒不窥园久，元非效仲舒。","新荷满沼密，蓝舁出门疏。","借问含烟晚，能胜裛露初。","愧无鱼戏句，弄翰白纷如。"]},{"t":"和子渊元夕","f":"七言律诗","c":["神岳嶕峣阙角齐，银蟾无影玉绳低。","风传丝管交加发，灯滉星河上下迷。","清醴横飞金凿落，香尘不染锦障泥。","谁知此夕斋祠客，近在宫城槐柳西。"]},{"t":"和子渊除夜","f":"七言律诗","c":["缇室重飞玉琯灰，物华全与斗杓回。","依依残腊无情别，历历新春满眼来。","强取酒卮浮翠柏，懒开粽叶觅杨梅。","男儿努力平生志，肯使功名落草莱。"]},{"t":"和公廙喜雪","f":"七言律诗","c":["向来河洛久愆阳，祷祀徒劳罄肃庄。","林雪飞花欣暂白，麦田濡叶未全黄。","城中稍觉桑薪贵，村外时闻社瓮香。","八使孜孜悯茕独，斯民那复畏凶荒。"]},{"t":"和王少卿十日与留台国子监崇福宫诸官赴王尹赏菊之会","f":"七言律诗","c":["儒衣武弁聚华轩，尽是西都冷落官。","莫叹黄花过佳节，且将素发共清欢。","红牙板急弦声咽，白玉舟横酒量宽。","青眼主公情不薄，一如省闼要人看。"]},{"t":"和王安之题独乐园","f":"五言律诗","c":["草浓初过雨，林静远含烟。","燕引新飞鷇，荷承半坠莲。","朋来惟有月，山见不须钱。","谁与同其乐，壶中浊酒贤。"]},{"t":"和乐道再以诗见寄","f":"七言律诗","c":["谏垣簪笔接英游，今日华颠昔日忧。","邂逅升沈皆是命，逍遥出处本无愁。","衡门不羡金门贵，藿食焉知肉食谋。","溟海榆枋各安分，蓬莱未必胜嵩丘。"]},{"t":"和乐道自河外南辕过宜芳雨晴和气景物可爱马上偶成","f":"五言律诗","c":["京洛春应老，河边初解颜。","碧浮烟际草，翠滴雨馀山。","目极褰帷外，诗成揽辔间。","满川桃李色，共喜传车还。"]},{"t":"和史诚之谢送张明叔梅台三种梅花","f":"七言律诗","c":["别后相惊两鬓霜，可怜梅蕊为谁芳。","台头日暖分三色，林下风清共一香。","正烂漫时游不足，忽离披去乐难常。","慇勤手折遥相赠，不欲花前独举觞。"]},{"t":"和白都官见赠","f":"七言律诗","c":["齿疏鬓白两眸昏，万事无堪老病身。","脱粟犹沾太仓禄，法官仍忝外台臣。","直缘迂僻求闲地，岂是孤高慕古人。","英俊满朝皆稷契，太山何少一飞尘。"]},{"t":"和冲卿喜雨偶成","f":"七言律诗","c":["万里风随快雨来，尘昏消伏旱光开。","物情濯热参差喜，天意为仁容易回。","帘映薄寒灯有晕，窗含虚白麝成煤。","君侯雅有江湖兴，萧洒何须气象催。"]},{"t":"和刘伯寿陪潞公禊饮","f":"七言律诗","c":["旌幢车骑满沙头，鼓吹喧繁画鹢浮。","十里罗纨光照地，千家帘幕远临流。","觞随洛水周公事，月映凤楼裴相游。","令典久堕今更举，行闻美俗遍中州。"]},{"t":"和同舍对菊无酒","f":"五言律诗","c":["黄花倚秋色，晔晔为谁开。","更使窥残榼，空令洗旧杯。","嗅香行缭绕，撚蕊立徘徊。","尽日柴门外，白衣来不来。"]},{"t":"和宇文公南涂中见寄","f":"七言律诗","c":["骢马乌纱游洛尘，未能全得自由身。","深惭白首恋微禄，不向青山为散人。","斥鴳卑飞聊取适，冥鸿高举益难亲。","蜀都迢递千馀里，徒诵新诗妙入神。"]},{"t":"和安之久雨","f":"五言律诗","c":["秋霖逢甲子，禾耳恐须生。","流俗幸无验，高田犹有成。","润唯藜莠得，烂与蕙兰并。","早晚浮云豁，逍遥赋晚晴。"]},{"t":"和尧夫见寄 其二","f":"五言律诗","c":["仁政如慈父，蒲人得所依。","教条前后接，风迹古今稀。","试郡才书最，还朝必奋飞。","西台旧班列，犹望绣衣归。"]},{"t":"和尧夫见寄 其一","f":"五言律诗","c":["志趣苦难合，伥伥何所依。","逢君始相照，知我信为稀。","忽报除书下，徒瞻征盖飞。","相思千里远，洛浦又春归。"]},{"t":"和尧夫首尾吟","f":"七言律诗","c":["尧夫非是爱吟诗，安乐窝中无所为。","古道白头无外用，今时青眼几人知。","嵩山洛水长相见，秋月春风不失期。","筋力虽衰才思壮，递年比较未尝亏。"]},{"t":"和次道大庆殿上元迎驾","f":"七言律诗","c":["凤律年华到尚新，九重气象已成春。","晓云低拂羽林仗，宿雨先清紫陌尘。","玉殿鸣鞘传警跸，彤庭委佩集簪绅。","阙前无复鱼龙戏，自有驩谣亿万人。"]},{"t":"和宋次道西都元日怀不疑并见寄","f":"五言律诗","c":["露冕优分竹，题舆佐画圻。","比年携手乐，兹日赏心违。","斋祀春来并，娱游别后稀。","谁怜从窭卒，草际犯寒归。"]},{"t":"和邠守宋度支来卜居与南园为邻","f":"七言律诗","c":["弱冠交游鬓发苍，饱谙官况好深藏。","闲居共买一廛地，尽老常依数仞墙。","虽喜卜邻同晏子，尚惭推宅异周郎。","何时税此凭熊驾，倚仗相迎立路傍。"]},{"t":"和伯常自郢州见寄","f":"七言律诗","c":["西郊去岁揖行人，柳暗花浓又一春。","坐想高风清入骨，沉吟佳句健生神。","潺湲杳霭烟波古，散诞逍遥兴趣新。","应笑洛阳车马道，缁衣未免化红尘。"]},{"t":"和伯镇再入馆","f":"五言律诗","c":["甘泉献赋人，流落浙江滨。","自叹三年谪，归来万事新。","铨衡时进对，户牖日相亲。","明主方思贾，非徒问鬼神。"]},{"t":"和君贶少林寺","f":"七言律诗","c":["达磨自云传佛心，绪言迷世到于今。","既携只履归西域，安得遗灵在少林。","孤月正明高殿冷，清风不断老松深。","谢公自爱山泉美，肯为幽禅此访寻。"]},{"t":"和君贶寄河阳侍中牡丹","f":"七言律诗","c":["真宰无私妪煦同，洛花何事占全功。","山河势胜帝王宅，寒暑气和天地中。","尽日玉盘堆秀色，满城绣毂走香风。","谢公高兴看春物，倍忆清伊与碧嵩。"]},{"t":"和君贶任少师园赏梅","f":"七言律诗","c":["寒压春头草未芽，喜闻置酒赏新葩。","官仪赫奕三川守，野意萧疏四皓家。","不用管弦妨淡泊，岂容桃李竞繁华。","昏鸦散乱传呼出，归路林间烛影斜。"]},{"t":"和君贶暮秋四日登石家寺阁晓泛洛舟 登阁","f":"五言律诗","c":["嬉游乘晓霁，登览犯秋寒。","不出埃尘外，安知在壤宽。","宫前断山碧，林表落霞丹。","欲下惜佳趣，相留更倚栏。"]},{"t":"和君贶题潞公东庄","f":"七言律诗","c":["嵩峰远叠千重雪，伊浦低临一片天。","百顷平皋连别馆，两行疏柳拂清泉。","国须柱石扶丕构，人待楼航济巨川。","萧相方如左右手，且于穷僻置闲田。"]},{"t":"和君锡雪后招探春 其二","f":"五言律诗","c":["繁霙回夜色，凌乱落春云。","虚幌寒相袭，华堂静不闻。","玉卮深可敌，银烛近微分。","谁念牛衣客，穷经白发纷。"]},{"t":"和吴仲庶寄吴瑛比部安道之子壮年致政归隐蕲春","f":"七言律诗","c":["负米承亲愿已赊，耻随鸡鹜啄泥沙。","一朝投绂真高士，万卷藏书旧世家。","齿发未衰非药物，山林不返为云霞。","庞眉尚有郎潜者，徇禄忧生直可嗟。"]},{"t":"和吴辨叔知凤翔见寄","f":"七言律诗","c":["岐阳府舍始相逢，四十馀春屈指中。","昔日布衣今露冕，当时小吏亦衰翁。","醉吟久作藏身计，条教应多及物功。","惟是綵衣难再著，长林极目起悲风。"]},{"t":"和宋子才致仕后岁旦见赠","f":"五言律诗","c":["闲官逢献岁，拜揖亦纷然。","须信家居日，方为已有年。","劬劳中外遍，名迹始终全。","伯玉空搔首，蹉跎愧在前。"]},{"t":"和张文裕初寒十首 其十","f":"五言律诗","c":["何处初寒好，初寒福善居。","长宵对灯火，满室聚诗书。","暂息登山屐，休脂下泽车。","所安容膝地，何必更多馀。"]},{"t":"和张文裕初寒十首 其九","f":"五言律诗","c":["何处初寒好，初寒游弈园。","林间叶未尽，篱底菊犹存。","结竹为庵小，开炉构火温。","谁言处城市，岑寂似丘樊。"]},{"t":"和张文裕初寒十首 其八","f":"五言律诗","c":["何处初寒好，初寒肃政台。","官闲免簿领，门静少尘埃。","天借风霜气，人无鹰隼猜。","庭荒馀老柏，尚有夕乌来。"]},{"t":"和张文裕初寒十首 其七","f":"五言律诗","c":["何处初寒好，初寒叠石溪。","山斜改昏晓，路曲失东西。","拾栗走村稚，凿垣巢乳鸡。","我来闲拥褐，曝背草檐低。"]},{"t":"和张文裕初寒十首 其六","f":"五言律诗","c":["何处初寒好，初寒喷玉泉。","折冰流谷口，飞溜落云边。","雀噪聚林杪，樵歌下石巅。","寻幽不思返，坐啸夕阳偏。"]},{"t":"和张文裕初寒十首 其五","f":"五言律诗","c":["何处初寒好，初寒禹凿门。","遥天露崖口，轻浪漱山根。","万佛龛苔老，一灯林霭昏。","渔梁杳相望，石濑夜声喧。"]},{"t":"和张文裕初寒十首 其四","f":"五言律诗","c":["何处初寒好，初寒太室山。","晴空烟澹泊，返照雪孱颜。","极目雁稍没，无心云自还。","犹馀拜表累，不得坐松间。"]},{"t":"和张文裕初寒十首 其三","f":"五言律诗","c":["何处初寒好，初寒洛水桥。","沙痕水清浅，风叶柳萧条。","关塞长涂直，嵩丘倒影遥。","凤楼虽在北，车马不尘嚣。"]},{"t":"和张文裕初寒十首 其二","f":"五言律诗","c":["何处初寒好，初寒洛汭宫。","翠华虽脉脉，佳气自葱葱。","阙角月华白，苑墙霜叶红。","都人心望幸，注目不离东。"]},{"t":"和张文裕初寒十首 其一","f":"五言律诗","c":["何处初寒好，初寒郏鄏城。","垂绅多俊彦，列第尽公卿。","裘马过从盛，门阑洒扫清。","谁家拥兽炭，尽日管弦声。"]},{"t":"和李八丈小雪同会有怀邻几","f":"七言律诗","c":["天禄淹回德齿尊，暂留汾曲两朱轓。","闲轩坐啸正飞雪，同舍倦游来及门。","空叹高歌如郢客，愧无佳赋似文园。","坐中犹欠邻几在，深负棋枰与酒樽。"]},{"t":"和李殿丞仓中对菊 其三","f":"五言律诗","c":["凉风正萧瑟，好月复徘徊。","幽兴眇不尽，芳樽时一开。","馀英盖红叶，坠露湿苍苔。","从此东篱下，应忘归去来。"]},{"t":"和李殿丞仓中对菊 其二","f":"五言律诗","c":["文案渐消散，仓闲吏已稀。","庭空数蝶下，夜静一萤飞。","爱赏忽成句，淹留时忘归。","高情虽不系，遇此独依依。"]},{"t":"和李殿丞仓中对菊 其一","f":"五言律诗","c":["高士寄朝市，迥然心迹殊。","秋风太仓里，黄菊满庭隅。","陶令成诗后，王公送酒无。","遥知厌俗事，未免强踌蹰。"]},{"t":"和杨卿中秋月","f":"五言律诗","c":["秋气平分夜，沈阴乍散天。","窥林初淡薄，照席忽孤圆。","泠入诗毫健，光浮醉弁偏。","嘉宾勿轻去，桂影正娟娟。"]},{"t":"和运使舍人北园饯别行憩三交僧舍冒雪宿百井关见寄","f":"七言律诗","c":["骊驹北上雪孱颜，韊矢前驱度汉关。","僧室松杉清照眼，驿亭烟火迥依山。","马衔边草枯犹瘦，雁怯胡云冷未还。","贱子不须回首问，鬓毛萧飒簿书间。"]},{"t":"和邵尧夫安乐窝中职事吟","f":"七言律诗","c":["灵台无事日休休，安乐由来不外求。","细雨寒风宜独坐，暖天佳景即闲游。","松篁亦足开青眼，桃李何妨插白头。","我以著书为职业，为君偷暇上高楼。"]},{"t":"和邵尧夫年老逢春","f":"七言律诗","c":["年老逢春春莫咍，朱颜不肯似春回。","酒因多病无心醉，花不解愁随意开。","荒径倦游从碧草，空庭慵扫自苍苔。","相逢谈笑犹能在，坐待牵车陌上来。"]},{"t":"和江邻几金铃菊","f":"五言律诗","c":["何处见佳菊，秋风汶水阳。","酒浮金铎细，露泛蜜房香。","不谓红尘地，相逢君子堂。","依然故人意，不减旧芬芳。"]},{"t":"和国子夏主簿李花","f":"七言律诗","c":["儒宫岑寂觉春闲，仙李繁花重压栏。","碎锦不飞蒙树合，素云攲亚举枝难。","能诗此日当推谢，捧赐他年足继桓。","更约雕盘荐秋实，岂徒秾艳一朝看。"]},{"t":"和始平公长句寄汉州何学士","f":"七言律诗","c":["势交倏忽易萧条，赖有伊人尚建标。","须信松筠凌雪茂，肯为蒲柳望秋凋。","钦贤高馆三年别，广汉专城百舍遥。","书纸如云诗叩玉，数凭疾翼度青霄。"]},{"t":"和始平公郡斋偶书二首 其二","f":"七言律诗","c":["平安候火出云间，区脱无尘刁斗闲。","汉相威声遥制敌，胡兵远迹夜开关。","赤松雅意思轻举，黄阁群心望复还。","玉帐牙旗空壮观，谢公高兴在东山。"]},{"t":"和始平公郡斋偶书二首 其一","f":"七言律诗","c":["文武从容两有馀，公槐将幕往来居。","已安四海如三杰，欲散千金比二疏。","今日监边亲跪毂，佗年入殿赐乘车。","武侯暂为苍生起，长忆隆中卧旧庐。"]},{"t":"和始平公梦中有怀归之念作诗始得两句而寤因足成一章","f":"五言律诗","c":["元宰抚洪钧，四海可熏灼。","至人养天真，视此犹婴缚。","出入金鼓威，寤寐琴樽乐。","乃知伊吕心，未始忘丘壑。"]},{"t":"和昌言官舍十题 其四 萱草","f":"五言律诗","c":["叶濯宿露翠，花迎朝日黄。","昔谁封殖此，俨列侍高堂。","达士隐于吏，孰为行与藏。","逍遥玩永日，自无忧可忘。"]},{"t":"和明叔九日","f":"五言律诗","c":["不奈衰须白，羞看朝鉴明。","聊凭佳节酒，强作少年情。","雨冷弊裘薄，风高醉帽倾。","如何不行乐，况复值秋成。"]},{"t":"和明叔游白龙溪","f":"五言律诗","c":["溪深荒径微，寻胜不知疲。","寒月影随马，晓风冰满髭。","行歌被褐叟，聚戏拾薪儿。","外野饶真趣，令人怀抱夷。"]},{"t":"和范景仁谢寄西游行记 其二","f":"七言律诗","c":["八水三川路渺茫，翠微深处白云乡。","目■懒拭如松液，领发频抓似栗房。","林壑不嫌无用物，形骸难入少年场。","缘苔蹑蔓知多少，千里归来屐齿苍。"]},{"t":"和范景仁谢寄西游行记 其一","f":"七言律诗","c":["洛川秦野郁相望，风物山河旧帝乡。","涧底逢人问樵径，松间系马宿僧房。","恨无同好携三雅，共讲前闻醉百场。","历遍胜游翻怅望，日边回首远烟苍。"]},{"t":"和复古小园书事","f":"五言律诗","c":["饱食复闲眠，风清雨霁天。","叶深时坠果，岸曲乍藏莲。","波面秋光净，林梢夕照鲜。","东家近亦富，满地布苔钱。"]},{"t":"和赵子舆龙州吏隐堂","f":"七言律诗","c":["四望逶迤万叠山，微通云栈落尘寰。","谁知吏道自可隐，未必仙家有此闲。","酒熟何人能共醉，诗成无事复相关。","浮生适意即为乐，安用腰金鼎鼐间。"]},{"t":"和吴朝议同年谢光与景仁同年见过","f":"七言律诗","c":["结绶东堂同发策，白头相值益相亲。","却思景祐无多日，共见元丰有几人。","天下高名归广受，古来交道重雷陈。","谢公身老才方壮，落笔成章字字新。"]},{"t":"和留守相公九月八日与潞公宴赵令园有怀去年与景仁秉国游赏","f":"七言律诗","c":["今岁台星聚洛中，甘棠前后雨阴浓。","英辞唱和诗千首，高宴游陪禄万钟。","木末霜繁花未落，云间字小雁相从。","西湖在望亲朋远，节物那堪处处逢。"]},{"t":"和聂之美雁","f":"五言律诗","c":["汲汲复栖栖，往来谁与期。","映云才可见，入雾杳难追。","羁枕梦初断，寒闺涕已危。","冥冥远缯缴，愧尔独知时。"]},{"t":"和钱学士呈邵兴宗","f":"七言律诗","c":["霜露苍苍宰树高，累茵列鼎重鸿毛。","蒹葭自幸犹依玉，髋髀何能学奏刀。","才薄无由禆覆焘，命奇不得报劬劳。","平生念此心先乱，蓼蓼难分莪与蒿。"]},{"t":"和景仁卜居许下","f":"七言律诗","c":["壮齿相知约岁寒，索居今日鬓俱斑。","拂衣已解虞卿印，筑室何须谢傅山。","许下田园虽有素，洛中花卉足供闲。","他年决意归何处，便见交情厚薄间。"]},{"t":"和范景仁夜读试卷","f":"七言律诗","c":["案前官烛堕花频，满目高文妙入神。","勇气先登势无敌，巧心后发语尤新。","好贤何啻三薰贵，求宝方知百汰真。","愚鲁自非凭骥发，昆山千里到无因。"]},{"t":"和景仁闻蝉","f":"五言律诗","c":["春林满岩绿，谁信已鸣蝉。","叶上正多露，山中别有天。","心闲宁感物，道合况忘年。","坐听生秋思，何须膝上弦。"]},{"t":"和景仁琼林席上偶成","f":"七言律诗","c":["念昔琼林赐宴归，綵衣绿绶正相宜。","将雏虽复慰心喜，负米翻成触目悲。","殿角花犹红胜火，樽前发自白如丝。","桂林衰朽何须恨，幸有新枝续旧枝。"]},{"t":"和景仁答才元寄示花图","f":"五言律诗","c":["高士闲居旧，名花独步今。","移从洛浦远，濯自锦江深。","传得巫山貌，非因延寿金。","不须天女散，已解动禅心。"]},{"t":"和道矩送客汾西村舍杏花盛开置酒其下","f":"七言律诗","c":["田家繁杏压枝红，远胜桃夭与李秾。","何事偏宜闲处植，无端复向别时逢。","林间暂系黄金勒，花下聊飞码碯钟。","会待重来醉嘉树，只愁风雨不相容。"]},{"t":"和王道粹垂拱早朝王范二直阁班列在前戏成小诗","f":"五言律诗","c":["霁日扶霜仗，祥烟覆晓班。","帝居回北斗，天阙竦南山。","紫殿鸿鸾肃，金门虎豹环。","蓬莱两仙伯，迥立白云间。"]},{"t":"和道粹春寒趋馆马上口占","f":"五言律诗","c":["残腊尚要春，清寒更著人。","雪华犹惜别，物意倍添新。","云压宫城重，风调玉漏匀。","行游宜结辔，九陌未多尘。"]},{"t":"和道粹雪夜直宿","f":"七言律诗","c":["天禄凝严近紫台，书帏夜对雪华开。","层楼直倚寒空出，清漏还从深殿来。","薄梦不成冰柱折，晓光先到玉花催。","兔园终是诸侯事，虚费相如能赋才。"]},{"t":"和潞公与昌言正叔游独乐园徘徊久之主人不至","f":"五言律诗","c":["茂勋成亮采，胜赏寄风流。","闲引翘林客，同为独乐游。","厌居华宇盛，翻爱弊庐幽。","愧不先操彗，迎尘立道周。"]},{"t":"和潞公真率会诗","f":"七言律诗","c":["洛下衣冠爱惜春，相从小饮任天真。","随家所有自可乐，为具更微谁笑贫。","不待珍羞方下箸，只将佳景便娱宾。","庾公此兴知非浅，藜藿终难继主人。"]},{"t":"咏史 其三","f":"五言律诗","c":["春风三阁上，珠翠日纷纷。","乐饮陶江月，清歌遏海云。","醉中失陈国，梦里入隋军。","玉树庭花曲，凄凉不可闻。"]},{"t":"咏史 其一","f":"五言律诗","c":["不事王侯者，翛然郑子真。","开田谷口美，荷锸白渠春。","德化移乡曲，声光动搢绅。","一时钟鼎贵，磨灭彼何人。"]},{"t":"咏史 其二","f":"五言律诗","c":["延陵腰利剑，上国使初通。","待我周游遍，逢君遣奠终。","晶荧系高树，萧瑟动寒风。","谁敢欺生死，苍苍照尔衷。"]},{"t":"咏寒士","f":"五言律诗","c":["洋洋泌水侧，蓬室苦萧条。","衣薄难胜夜，厨闲空过朝。","笑谈东郭履，歌诵买臣樵。","但问才何似，无疑卿相遥。"]},{"t":"夜发长垣","f":"五言律诗","c":["长涂暑气剧，永日卧邮亭。","画伏如墙鼠，宵行似野萤。","歇鞍沙月白，拂面柳风醒。","历历瞻云汉，谁为二使星。"]},{"t":"奉同运使陈殿丞惜洛阳牡丹为霜风所损","f":"七言律诗","c":["名花多种欲纷敷，一夕霜风非所虞。","节物偶然何足道，人情遗恨不能无。","飘飖健笔诗千首，惆怅东风酒百壶。","纵使前春满朱槛，使车那复滞西都。"]},{"t":"奉同道矩谢始平公惠砚","f":"五言律诗","c":["爵台今已倾，飘瓦出芜城。","还入缣缃用，尤资笔墨精。","相君怜古物，内史擅书名。","聊用飞军檄，何愁楯鼻平。"]},{"t":"奉和始平公忆东平 其一","f":"七言律诗","c":["相印东临汶水阳，两看春叶与秋霜。","登山置酒延邹湛，上马回鞭问葛强。","溪竹低垂寒滴翠，露荷相倚净交香。","宵衣深念长城固，肯得从容傲醉乡。"]},{"t":"奉和始平公忆东平 其二","f":"七言律诗","c":["千岩秀色拥晴川，万顷陂光上下天。","委地鱼盐随处市，蔽空桑柘不容田。","讼庭虚静官曹乐，儒服宽长邑里贤。","不为从知方负羽，独乘鱼艇老风烟。"]},{"t":"奉和始平公喜闻昌言修注","f":"七言律诗","c":["凤口除书下九阍，簪绅拭目仰殊恩。","晓提麟笔依华盖，日就螭坳记圣言。","桃李新阴方蔼蔼，骅骝老志更轩轩。","主人喜见相如达，趣召邹枚洗玉樽。"]},{"t":"奉和御制龙图等阁观三圣御书","f":"五言律诗","c":["积厚丕丕业，重光郁郁文。","宝书垂列宿，玉字切浮云。","散帙鸣銮驻，充庭杂佩分。","愿移天纵艺，似续圣功勤。"]},{"t":"和景仁西湖泛舟","f":"七言律诗","c":["满船歌吹拂春湾，天外晴霞水底斑。","谁信飞觞临绮席，独能回首望青山。","东门车马匆匆别，西洛风烟寂寂闲。","叠石溪头应更好，却输野叟坐林间。"]},{"t":"始平公以光得免使北赐之以诗谨依韵酬和","f":"七言律诗","c":["皇华将命得人难，专对非才辄自言。","幸免驱车涉沙漠，尚容载笔侍宣温。","不唯羞屈穹庐膝，无奈常游魏阙魂。","衮职区区未能补，何时馀论奉清樽。"]},{"t":"始平公新作双樗庵命光为诗","f":"五言律诗","c":["间气生王佐，多才秉国钧。","栋隆凭杞梓，节劲仰松筠。","底绩承平业，遗荣寿考身。","结庐依散木，退让乐天真。"]},{"t":"宜甫东楼晚饮","f":"五言律诗","c":["宾主俱欢醉，高楼迥倚空。","形忘羁检外，酒散笑谈中。","晚市烟初白，秋园叶半红。","登临不厌数，朝夕是寒风。"]},{"t":"忝职谏垣日负忧畏缅思云夫处士老兄萧然物外何乐如之因成浮槎诗寄献以抒鄙怀","f":"五言律诗","c":["秋水浮槎客，漂如一叶轻。","鸥群须仗信，鲸口几忘生。","耿耿天津阔，滔滔海浪惊。","何时还故土，怀糈问君平。"]},{"t":"或谓光嗤景仁谈禅而自谈又因用前韵为景仁解禅","f":"五言律诗","c":["贱子悟已久，景仁迷自今。","良因拯溺急，是致涉波深。","到岸何须筏，挥锄不见金。","浮云任来往，明月在天心。"]},{"t":"枇杷洲","f":"五言律诗","c":["周官敛珍味，汉苑结芳根。","何意荒洲上，犹馀嘉树存。","犯寒花已发，迎暑实尤繁。","愿逐蒲萄使，离宫奉至尊。"]},{"t":"苦雨","f":"五言律诗","c":["积雨欲侵旬，朝晡漫不分。","苍凉微露日，惨澹已生云。","地半成泥滓，天应厌垢氛。","时闻度鸧鸹，空外自为群。"]},{"t":"英宗皇帝挽歌辞三首 其三","f":"五言律诗","c":["谏省臣无状，龙鳞昔屡婴。","恩深忘位贱，义重觉生轻。","不正诛锄法，仍蒙奖叹荣。","百身何足报，天造固难名。"]},{"t":"英宗皇帝挽歌辞三首 其二","f":"五言律诗","c":["虹瑞流朱邸，童髦侍紫宸。","简心天与子，授位帝知人。","学古功时敏，钩深道日新。","宜然三百载，民物仰威神。"]},{"t":"英宗皇帝挽歌辞三首 其一","f":"五言律诗","c":["盛德师尧舜，英姿肖祖宗。","太阳光遍照，沧海量兼容。","鸿业知能继，齐民望可封。","如何未五载，已上鼎湖龙。"]},{"t":"虎牢关","f":"五言律诗","c":["天险限西东，难知造化功。","路邀三晋会，势压两河雄。","馀雪沾枯草，惊飙卷断蓬。","徒观争战处，今古索然空。"]},{"t":"诗寄云夫处士老兄兼呈知府待制八丈","f":"五言律诗","c":["一鹗曾飞奏，中林下鹤书。","今乘使君马，重到逸人居。","松竹过从久，闾阎惠爱馀。","只应棠树影，比旧更扶疏。"]},{"t":"郑侍郎挽歌辞","f":"五言律诗","c":["云梦气回复，比肩生隽豪。","司农家学富，廷尉里门高。","骐骥昔千里，凤凰今一毛。","即邱馀庆在，终应吕虔刀。"]},{"t":"金山寺","f":"五言律诗","c":["香刹冠嵯峨，松门络薜萝。","风清尘不到，岸阔鸟难过。","欲雨江声怒，新晴海气多。","行舟未摇棹，回望隔烟波。"]},{"t":"南园杂诗六首 莲房","f":"五言律诗","c":["莲房前后熟，供啖不须齐。","肉嫩山蜂子，棱深天马蹄。","尚连馀蕊在，深映乱荷低。","脆美知新采，近根犹带泥。"]},{"t":"南园杂诗六首 萤","f":"五言律诗","c":["林塘荒湿地，向夕已飞萤。","月没蛩吟砌，露凉人在庭。","随风疑落烬，过水乱疏星。","学子灯前寝，谁将尔照经。"]},{"t":"南园饮罢留宿诘朝呈鲜于子骏范尧夫彝叟兄弟","f":"五言律诗","c":["园僻青春深，衣寒积雨阕。","中宵酒力散，卧对满窗月。","旁观万象寂，远听群动绝。","只疑玉壶冰，未足比明洁。"]},{"t":"南湖 其二","f":"五言律诗","c":["海雁长桥北，乘闲日日来。","游鱼自应乐，宿鸟不相猜。","弱柳周遭合，芳花次第开。","梁王昔游集，后乘列邹枚。"]},{"t":"南湖 其一","f":"五言律诗","c":["宋都南野水，花柳媚名园。","鸟起沙留迹，鱼惊浪结痕。","朱桥通别岛，白路出荒村。","城邑虽云迩，常无车马喧。"]},{"t":"复古诗首句云独步复静坐辄继二章 其一 独步","f":"五言律诗","c":["踽踽出东轩，徐徐步小园。","何须从吏卒，亦不引儿孙。","蹑屐寻莎径，携筇拨水源。","愁闻俗客到，唯说市朝喧。"]},{"t":"复古诗首句云独步复静坐辄继二章 其二 静坐","f":"五言律诗","c":["一榻仅容膝，身心俱寂然。","直缘知乐内，亦不为安禅。","棐几陈编掩，竹窗残局捐。","尚馀喧噪在，野鸟与林蝉。"]},{"t":"复用三公燕集韵酬子骏尧夫","f":"五言律诗","c":["官闲虚室白，粟饱太仓红。","朝夕扫三径，往来从二公。","蒹葭徒倚玉，燕雀岂知鸿。","相遇辄同醉，惟愁樽酒空。"]},{"t":"宣徽使河东经略使郑文肃公挽歌 其二","f":"五言律诗","c":["柳翣丧容盛，江山故国遥。","清时独长往，何日重来朝。","事与秋云断，荣如晓梦消。","西风虎丘路，马鬣又嶕峣。"]},{"t":"宣徽使河东经略使郑文肃公挽歌 其一","f":"五言律诗","c":["璿玑敷帝命，金节护边兵。","尽付将军制，真为儒者荣。","扶摇方上击，濛汜忽西倾。","罢市人相吊，纷纷满百城。"]},{"t":"侍读王文公挽歌二首 其二","f":"五言律诗","c":["杖底潜蛇影，门阴集戴鵀。","玉楼新记就，石椁旧铭沈。","箧有封峦札，籯无遗子金。","寂寥封马鬣，秋色净松林。"]},{"t":"侍读王文公挽歌二首 其一","f":"五言律诗","c":["石室书编富，金华讲席重。","荐神归博洽，鸣玉称雍容。","贰负累囚象，尸臣古瑑踪。","老成今已矣，咨访欲谁从。"]},{"t":"故侍读学士张公哀辞二首 其二","f":"五言律诗","c":["凶梦歌洹水，妖巢集戴鵀。","未尝馀俸禄，无以具衣衾。","袁涣分仓谷，翁归赐府金。","佗年纯固传，宁使令名沈。"]},{"t":"故侍读学士张公哀辞二首 其一","f":"五言律诗","c":["喜愠与荣枯，居之悉晏如。","稍门多执笔，至老不抛书。","常愧无能极，曾沾清论馀。","秋风郭门外，雨泣望丧车。"]},{"t":"故相国颍公挽歌辞三首 其三","f":"五言律诗","c":["沧波与邓林，鱼鸟久飞沉。","一旦成陈迹，何人识寸心。","高山亡景行，流水失知音。","泪尽离东阁，归来破故琴。"]},{"t":"故相国颍公挽歌辞三首 其二","f":"五言律诗","c":["铭旌远明灭，骑吹去低昂。","三鼎功名大，重泉日月长。","鹤飞来吊客，牛卧卜连冈。","车马还城郭，悲风满白杨。"]},{"t":"故相国颍公挽歌辞三首 其一","f":"五言律诗","c":["儒衣临绝塞，庙略运奇兵。","缓带羌尘静，灵旗海雾清。","公心结明主，阴德庇群生。","名遂身仍退，人间五福并。"]},{"t":"故绛城","f":"五言律诗","c":["文公恢霸略，征讨辅周衰。","奕世为盟主，诸侯听会期。","山河表里在，朝市古今移。","欲访虒祁处，乡人亦不知。"]},{"t":"故翰林彭学士挽歌 其三","f":"五言律诗","c":["祖奠垂将撤，笳箫俨欲行。","野寒嘶故马，树转出新旌。","泉路幽无底，鱼灯暧不明。","如何赍美志，郁郁向佳城。"]},{"t":"故翰林彭学士挽歌 其一","f":"五言律诗","c":["夙昔游清贯，时流籍重名。","雠书石渠秘，视草玉堂荣。","吉兆虚三鳝，凶期告两楹。","子云思故国，坟树必西倾。"]},{"t":"春日思景仁","f":"五言律诗","c":["去岁洛城中，嬉游处处同。","从离崿岭北，常梦潩泉东。","草绕春街碧，花繁夕市红。","临风默惆怅，想像白眉翁。"]},{"t":"春祠致斋寄呈景仁次道","f":"五言律诗","c":["比日聚官舍，笑言曾未厌。","暂成挥手别，各有侍祠严。","晴景朝朝丽，春容物物添。","解斋当共醉，莫遣此期淹。"]},{"t":"春猎","f":"七言律诗","c":["小苑微寒春雁飞，石关宫外草萋萋。","汉家旌旆连围合，秦国山川入望低。","花色才临珠缀发，柳阴欲傍金堤齐。","韩嫣承恩来视兽，飞尘遥出建章西。"]},{"t":"柳溪对雪","f":"五言律诗","c":["春风不胜雪，散漫度龙沙。","密映缘溪柳，争飞乱眼花。","鸱夷赊美酒，油壁系轻车。","塞下芳菲晚，聊将当物华。"]},{"t":"泉水诗送吴都官分司归和州","f":"五言律诗","c":["泉水出幽谷，原流本自清。","萦回遍中国，浩荡入东瀛。","峡口春雷怒，潭心晓鉴平。","悠悠随所值，行止两无情。"]},{"t":"独乐园新春","f":"七言律诗","c":["春风与汝不相关，何事潜来入我园。","曲沼揉蓝通底绿，新梅剪綵压枝繁。","短莎乍见殊堪喜，鸣鸟初闻未觉喧。","凭仗东君徐按辔，旋添花卉伴芳樽。"]},{"t":"相国广平文简程公挽歌二首 其二","f":"五言律诗","c":["帝诰封泥紫，皇坟杀简青。","坐谈安玉垒，专对詟龙庭。","黼黻昭文理，冰霜瑩典刑。","英灵入箕尾，终古作天星。"]},{"t":"相国广平文简程公挽歌二首 其一","f":"五言律诗","c":["明直君臣合，安危将相兼。","金章四辅贵，玉帐万兵严。","禦侮长城隐，临繁利刃铦。","南山霣岩石，何以慰民瞻。"]},{"t":"神宗皇帝挽词五首 其四","f":"五言律诗","c":["鳌禁叨承诏，金华侍执经。","微生轻草芥，圣泽阔沧溟。","鹿性安林野，葵心注阙庭。","尧云不可望，白首涕飘零。"]},{"t":"神宗皇帝挽词五首 其三","f":"五言律诗","c":["至德成无象，徽名避不居。","期门弋猎绝，步辇宴游疏。","钱列金釭暗，兵严武帐虚。","蓬莱日晏仗，犹望驾宫车。"]},{"t":"神宗皇帝挽词五首 其二","f":"五言律诗","c":["听政涉中昃，观书达夜分。","周王忘自逸，汉祖不知勤。","棣萼因心友，云章落笔文。","它年紬石室，光大继皇坟。"]},{"t":"秋日寄山中友人","f":"五言律诗","c":["昨夜听秋风，霜崖几树红。","心随新雁去，宛至碧溪东。","圣主搜渔钓，林岩今已空。","胡为执高节，憔悴久山中。"]},{"t":"秋日登观信亭","f":"五言律诗","c":["西风连夜雨，草树已萧条。","宿霭稍零落，寒山更寂寥。","林红犹带日，岸白欲生潮。","新雁来何处，离离天际遥。"]},{"t":"秋夜","f":"五言律诗","c":["城上调秋角，烟间发暝钟。","风枝摇宿鸟，霜草覆寒蛬。","久负观书乐，端愁束带恭。","暂因群吏散，还得遂幽慵。"]},{"t":"秋夜","f":"五言律诗","c":["浮云一消散，星斗粲长天。","浩露洒翠柏，清香生白莲。","体凉犹衣葛，耳静已无蝉。","坐久群动息，秋空唯寂然。"]},{"t":"秋夜望月","f":"五言律诗","c":["万里氛昏歇，金波秋更明。","星连河渚闇，风绕桂枝生。","鳷鹊临华馆，新丰落故城。","古今佳赏尽，殊自有馀清。"]},{"t":"秋雨新霁游水北马上偶成","f":"五言律诗","c":["秋色与秋声，萧然满洛城。","未霜林叶赤，新雨野风清。","水气侵肌冷，岚光刮眼明。","谁云景如画，但恐画难成。"]},{"t":"胡太傅挽歌二首 其二","f":"五言律诗","c":["裴回游内禁，密勿赞鸿枢。","阴德加民物，清名服士夫。","天方遗一老，星忽陨三吴。","疑从龙髯去，乘云在帝都。"]},{"t":"胡太傅挽歌二首 其一","f":"五言律诗","c":["行冠乡人品，文为学者师。","黄裳蕴厚德，玉律俨清规。","大节人难夺，嘉谟世莫知。","仪型不可见，遗烈满丰碑。"]},{"t":"贻宋四行简迪","f":"五言律诗","c":["离群如几辰，屈指十青春。","不意轮蹄迹，共兹京洛尘。","文场投漆契，客路转蓬身。","别易相逢阔，过从莫厌频。"]},{"t":"送丁正臣知蔡州","f":"词","c":["䟃?汝水滨，千骑拥朱轮。","悬瓠遗基古，鞶囊吉梦新。","丹心留紫闼，清耳远红尘。","须识明君意，先应试治民。"]},{"t":"送丁正臣通判复州","f":"五言律诗","c":["得失固有命，世人空自劳。","冬温少霜雪，松短没蓬蒿。","孤宦千里远，荣名一旦高。","回看碌碌者，太华与秋毫。"]},{"t":"送二同年使北 吕济叔","f":"五言律诗","c":["华缨下玉除，天子宠匈奴。","虽复夷风陋，犹知汉使殊。","夜烽沈不举，秋柝寂无虞。","何必燕然刻，苍生肝脑涂。"]},{"t":"送二同年使北 李公素","f":"五言律诗","c":["云愁雪欲零，四牡出郊坰。","古塞烟华紫，寒沙日气青。","金门秘鸡树，朱节耀龙庭。","几夜天街北，遥占汉使星。"]},{"t":"送人为闽宰","f":"五言律诗","c":["万里东瓯外，溪山秀出群。","乡人皆嗜学，太守复工文。","正用慈良化，居无牒诉纷。","谁云远京国，佳政日相闻。"]},{"t":"送才元守广安军归成都觐省","f":"五言律诗","c":["皂盖五骅骝，今来异昔游。","箪壶交里舍，铙吹下瀛州。","寿酒行当举，归鞭不可留。","春光久相待，先在锦江头。"]},{"t":"送云卿知卫州","f":"五言律诗","c":["汗简成新令，褰帷刺剧州。","韦平家法在，邵杜治声优。","野竹交淇水，秋瓜蔓帝邱。","三年归奉计，肯顾石渠游。"]},{"t":"送元待制出牧福唐","f":"五言律诗","c":["瓯越东南美，田肥果稼饶。","况怀新赐绶，重过旧题桥。","食足奸回熄，风移狱犴销。","长才报政速，铃阁日逍遥。"]},{"t":"送王书记之官永兴","f":"五言律诗","c":["白发添新镊，红尘满弊衣。","人生适未值，吾道岂云非。","巩洛风烟远，函秦草树微。","长安春酒美，行乐勿令希。"]},{"t":"送王伯初通判婺州","f":"五言律诗","c":["煜爚屏星驾，迢遥婺女区。","岚光晴向背，溪溜暖萦纡。","万室鸣机杼，千艘隘舶舻。","若逢耆旧问，能说隐侯无。"]},{"t":"送王校理守琅琊","f":"五言律诗","c":["金门倦鸣玉，千骑出东方。","封略依沧海，枌榆近故乡。","秦碑苔蚀字，鄅稻日翻芒。","国吏遥应识，当年丞相郎。"]},{"t":"送王都官官满还都","f":"五言律诗","c":["粹美清庙器，可嗟沉下僚。","优游仲举坐，洋溢海沂谣。","奏课应居首，知音况满朝。","从今黄鹄举，眼冷看青霄。"]},{"t":"送王著作西京签判","f":"五言律诗","c":["古来都邑美，孰与雒阳先。","况复元侯贵，兼之从事贤。","玦离横阙塞，珠曲逗伊川。","慰眼登临乐，送君空惘然。"]},{"t":"送王殿丞西京签判","f":"五言律诗","c":["清白世风存，王公复有孙。","挺生如玉树，不竭似淮源。","日背嵩峰紫，春添洛水喧。","幕中多胜友，肯使负芳樽。"]},{"t":"送王殿丞知眉山县 其一","f":"五言律诗","c":["畴昔侍严亲，俱为綵服人。","游兰已多益，得桂复同春。","风树悲欢异，萍波聚散频。","峡中尽遗事，何处不沾巾。"]},{"t":"送王瓘同年河南府司录","f":"五言律诗","c":["綵服昔为儿，随亲宦洛师。","至今馀梦想，常记旧游嬉。","佐史头应白，书楼树已攲。","闻君行有日，使我泪交颐。"]},{"t":"送冯状元归鄂州","f":"五言律诗","c":["夙昔负奇节，琅然为众殊。","下韝连得俊，出手尽成卢。","喜气兼邻曲，荣名溢道涂。","风云俱动色，非复旧江湖。"]},{"t":"送史馆任祠部河东转运使","f":"五言律诗","c":["问望簪绅旧，恩华雨露重。","图书周内史，汾浍晋全封。","秀发千寻壁，寒生百鍊锋。","归时门有戟，惜别更从容。"]},{"t":"送田校理知晋州","f":"五言律诗","c":["铨筦萃贤豪，夫君主剧曹。","长才沛馀裕，众论蔚推高。","逮此分符贵，知无顿刃劳。","公卿如有缺，不独赐金褒。"]},{"t":"送白都官归长安","f":"七言律诗","c":["丈夫那肯浪低眉，薄宦空添鬓里丝。","泸水归来山浩荡，都门辞去菊离披。","黄鸡白酒五陵乐，杜曲樊川九谷宜。","复见夫君行直道，崆峒气俗未应衰。"]},{"t":"送仲更归泽州","f":"七言律诗","c":["太行横拥巨川回，三晋由来产异才。","展墓乘春走乡陌，负书拂晓下兰台。","河阳路侧花应合，天井关头雪未开。","会使乡人惊六印，莫羞今日弊裘来。"]},{"t":"送光禄王卿致仕归荆南","f":"七言律诗","c":["九列谁云非显涂，人生已不负为儒。","拂衣长揖夔龙贵，散发还为黄绮徒。","白鹤归飞心自远，青霞高举势何孤。","千金尽与乡人费，不向江头买木奴。"]},{"t":"送冲卿通判河中府","f":"七言律诗","c":["闻道名都行有期，依然想见昔游时。","寒光一曲秋河转，翠岭三条夕照移。","孤竹旧风民有让，重华馀教俗无疵。","不须到日方登历，已在君家十二诗。"]},{"t":"送刘仪先辈大名尉","f":"五言律诗","c":["潭潭相府开，旌骑拥三台。","闻道廷中吏，无非天下才。","策名新振拔，把板尚低回。","勿为卑飞困，青冥尽此来。"]},{"t":"送刘仲通赴京师","f":"五言律诗","c":["圣朝方考牧，蕃育寄才能。","屡别良可叹，闲游不复曾。","行尘遵洛汭，朝骑对觚棱。","瀍上秋台迥，归来正好登。"]},{"t":"送刘观察知洺州","f":"五言律诗","c":["汉家英俊士，衮衮出金阊。","久袭通侯籍，新腰太守章。","畛封连故赵，庐井带清漳。","春色迎铙吹，应忘道路长。"]},{"t":"送华亭沈主簿","f":"五言律诗","c":["执袂青门道，萧萧马欲东。","暮云零落翠，远树浅深红。","楚泽吟声里，吴山醉眼中。","相思杳何许，野鹤唳高风。"]},{"t":"送向防禦知陈州","f":"五言律诗","c":["千骑去翩翩，专城上少年。","韦平家好学，阴马世称贤。","官用才能进，恩非雨露偏。","想闻河润远，封畛帝畿连。"]},{"t":"送尧夫知河中府二首 其二","f":"五言律诗","c":["河抱城根曲，山侵地势斜。","周馀古楼观，舜俗旧人家。","回首游从阔，装怀牒诉哗。","何时重载酒，同醉洛阳花。"]},{"t":"送尧夫知河中府二首 其一","f":"五言律诗","c":["耆老承风旧，丝纶锡命新。","展禽安屡黜，原宪乐常贫。","执志穷通壹，论交表里真。","但祈深自重，膏泽望斯民。"]},{"t":"送师道知长溪因归觐省","f":"五言律诗","c":["羁旅帝城久，逢人青眼稀。","闻君又当去，使我益思归。","佳色邻乡树，高堂望綵衣。","春流先自疾，心出片帆飞。"]},{"t":"送杨太祝知长洲县","f":"五言律诗","c":["三吴佳县首，民物旧熙熙。","专用清谈治，非如俗吏为。","林疏丹橘迥，稻熟白芒攲。","宜使民无忘，严修太伯祠。"]},{"t":"送朱校理知潍州","f":"七言律诗","c":["东国连年水伤稼，使君到部即行春。","茫茫四野潢污竭，郁郁万行桑柘新。","俗不好奢田器贵，狱无留系吏家贫。","齐人忽怨归朝速，自是承明侍从臣。"]},{"t":"送朱职方提举江淮运盐","f":"五言律诗","c":["熬漉沧波耗，征输泽国贫。","婴罗矜赤子，运筴借能臣。","拜手觚棱晓，浮舟狼汤春。","东南待苏息，别酒莫逡巡。"]},{"t":"送次道知太平州","f":"五言律诗","c":["狼汤春流满，芜湖候吏迎。","旌旟晓日丽，钲鼓野风清。","暂喜红尘远，休嗟素发生。","专城方四十，自古以为荣。"]},{"t":"送计先辈尉宗城","f":"五言律诗","c":["红尘久帝城，高价动公卿。","竹柏寒方茂，骅骝老更成。","冰霜驱马瘦，书剑束装轻。","丞相虚东阁，遥知倒屣迎。"]},{"t":"送齐学士知荆南","f":"七言律诗","c":["汉家太守治才高，楚国山川气象豪。","旗旆逶迤蟠梦泽，楼船赑屃压江涛。","雄名谁复知宣武，遗爱犹应祀叔敖。","何必三年求奏计，诏书朝夕赐金褒。"]},{"t":"送何万下第归蜀 其二","f":"五言律诗","c":["失意流年老，残春对夕阳。","可堪临远道，更复举离觞。","花柳已萧索，云山复渺茫。","西风如有意，音信勿相忘。"]},{"t":"送何万下第归蜀 其一","f":"五言律诗","c":["十上终无就，才高定复论。","清时守儒术，白首在丘园。","远树隐残日，孤烟生暮村。","扬鞭万里去，几许不销魂。"]},{"t":"送何济川为庞公使庆阳席上探得冬字","f":"五言律诗","c":["幕府遥三舍，传车乘一封。","忠深轻远道，醉暖失严冬。","圁水犹飞檄，芦阕未灭烽。","贤侯虽喜士，难得久从容。"]},{"t":"送吴仲庶知江宁","f":"五言律诗","c":["江南佳丽地，人物自风流。","青骨灵祠在，黄旗王气收。","衣冠馀旧俗，歌颂乐贤侯。","正恐还朝速，江山未遍游。"]},{"t":"送吴驾部知真州","f":"五言律诗","c":["向托屏星驾，同随丞相车。","终朝容懒拙，经岁庇迂疏。","共此趋云阙，旋闻建隼旟。","江淮一都会，游刃必多馀。"]},{"t":"送吴辨叔大名司户 其二","f":"词","c":["致远必自近，如君岂椽曹。","鱼龙试春浪，松栝露秋毫。","错落辞华富，䃘?气节高。","垂天起肤寸，无叹走尘劳。"]},{"t":"送吴辨叔大名司户 其一","f":"五言律诗","c":["元宰司宫钥，旌旄压大河。","敢言趋府倦，私叹折腰多。","机发何妨避，光尘未免和。","艰难方远到，庆阀肯蹉跎。"]},{"t":"送宋郎中知凤翔府","f":"五言律诗","c":["昔解陈仓印，于今二十秋。","双凫久东上，五马重西游。","铙骑行关外，壶浆拥道周。","民心已化服，条教不更修。"]},{"t":"送张寺丞知富顺监","f":"五言律诗","c":["汉家五尺道，置吏抚南夷。","欲使文翁教，兼令孟获知。","盘羞蒟酱实，歌杂竹枝辞。","取酒须勤醉，乡关不可思。"]},{"t":"送张学士两浙提点刑狱","f":"五言律诗","c":["朝家重典刑，书府借时英。","钲鼓喧江下，云山拂眼清。","秋风鲈鲙美，书日锦衣荣。","勿似朱翁子，空令守邸惊。"]},{"t":"送张秘校知分宁","f":"七言律诗","c":["百里大夫官不轻，莫嗟领上发垂星。","人生谷禄偏宜晚，世路艰难不厌经。","数曲秋江萦县白，几峰霁色入帘青。","于公向日多阴德，已有鹓雏在帝庭。"]},{"t":"送张都官江南东路提刑","f":"五言律诗","c":["楚俗号难治，司刑尤择贤。","危疑片言决，舒惨一方专。","松不彫寒色，丝曾断直弦。","清风过江外，应在下车前。"]},{"t":"送张景淳知邵武军","f":"五言律诗","c":["闽岭窅何在，东南千里遥。","仳离伤草草，会合更迢迢。","隋岸微吹絮，吴江欲上潮。","肯无同舍念，回首弭轻桡。"]},{"t":"送李学士使北","f":"五言律诗","c":["征盖霜空迥，飘飘迎塞鸿。","虏牙侵海角，汉节下天中。","酒薄阴山雪，裘寒易水风。","边声不可听，归思浩无穷。"]},{"t":"送李益之侍郎致政归庐山 其二","f":"五言律诗","c":["水底元无月，衣中自有珠。","六尘皆外物，万法尽迷涂。","瀑布寒云湿，觚棱瑞气扶。","遥知至乐地，不异在京都。"]},{"t":"送李益之侍郎致政归庐山 其一","f":"五言律诗","c":["儒业金华贵，归心白鹤孤。","江山依旧在，轩冕向来无。","啸咏谁当共，登临未索扶。","浩然知此乐，迥与世人殊。"]},{"t":"送杨秘丞通判扬州","f":"七言律诗","c":["苦闻小杜说扬都，当昔豪华今在无。","江势横来控南楚，地形前不瞰东吴。","万商落日船交尾，一市春风酒并垆。","得意莫忘京国友，踏尘冲雪奉朝趋。"]},{"t":"送沈寺丞知南昌县","f":"七言律诗","c":["长江湛湛带枫林，古木寒云县寺深。","老吏不能容狡狯，细民无复有冤侵。","洪崖丹井闻犹在，徐孺衡门说可寻。","宁复淹留如宝剑，更令牛斗气沈沈。"]},{"t":"送苏屯田知单州","f":"五言律诗","c":["佳郡望都城，相闻击柝声。","宾朋才执别，耆旧已前迎。","綵服当年戏，骊驹此日荣。","弦歌应尽在，琴调不须更。"]},{"t":"送周寺丞畋知洛南","f":"五言律诗","c":["太华指商于，中间百里馀。","稍行山驿远，渐与世尘疏。","楚塞参差接，秦民错杂居。","惜哉非綮肯，不足试投虚。"]},{"t":"送昌言舍人得告还蜀三首 其三","f":"五言律诗","c":["富贵动归思，由来光里闾。","戒门羞主父，负弩笑相如。","外物有荣悴，中心无戚疏。","遥知见亲旧，不改布衣初。"]},{"t":"送昌言舍人得告还蜀三首 其二","f":"五言律诗","c":["悽怆怀桑梓，劬劳咏蓼莪。","树风今远矣，鼎食奈悲何。","剑阁登车近，秦关屈指过。","腾装才首路，夕梦已江沱。"]},{"t":"送昌言舍人得告还蜀三首 其一","f":"五言律诗","c":["迢递铜梁道，凝严青琐闱。","负书当日去，鸣玉此时归。","乡树迎朱毂，江花照锦衣。","临邛不足并，荣耀古今稀。"]},{"t":"送昌言知宿州","f":"五言律诗","c":["炜炜符离守，中流簇鼓旂。","柳阴浓不断，舟势激如飞。","魏阙行归奏，承明秪暂违。","星轺晨夜度，尺素勿令稀。"]},{"t":"送魏寺丞赴辟秦州判官","f":"五言律诗","c":["征西大府开，后乘得高才。","区脱烽烟静，渠搜职贡来。","陇云低玉帐，羌舞奉金罍。","信美从军乐，脩梧茂帝台。"]},{"t":"送罗郎中管勾玉局观","f":"五言律诗","c":["官名为玉局，已与俗尘疏。","钟出寒松迥，香疑古殿虚。","乡闾非甚远，俸禄岂无馀。","谁道神仙乐，神仙恐不如。"]},{"t":"送郑推官赴邠州 其三","f":"五言律诗","c":["骄虏已归计，圣朝方寝兵。","时闻候火入，非复塞尘惊。","秋岭无南牧，春田恣北耕。","休穷西海路，辛苦学甘英。"]},{"t":"送郑推官赴邠州 其二","f":"五言律诗","c":["百榼行春乐，千弓从猎豪。","苦吟边月冷，飞镝野风高。","奇策鞭殊俗，长缨系不毛。","输君跃马贵，一等着青袍。"]},{"t":"送郑推官赴邠州 其一","f":"五言律诗","c":["形便豳公国，旌旗拥将坛。","秦云低落日，塞树怯春寒。","草檄无留思，投壶不废欢。","还应笑黄卷，寂寂守儒官。"]},{"t":"送峡州陈廉秘丞 其三","f":"五言律诗","c":["地险三巴口，江流百折蟠。","驺珂通峡响，门戟照秋寒。","翠壁虎牙石，素花狼尾滩。","孙刘置栅处，细为写图看。"]},{"t":"送峡州陈廉秘丞 其二","f":"五言律诗","c":["郡府猿声外，旌旗鸟道边。","楼高出楚塞，烟霁识巴船。","襦裤嗟来暮，簪绅惜外迁。","皇仁矜远俗，非谓意疏贤。"]},{"t":"送峡州陈廉秘丞 其一","f":"五言律诗","c":["宜都贤太守，治迹古人齐。","虎负众子去，凤环群鸟栖。","行增颍川秩，别降武都泥。","正恐还朝速，春林未子规。"]},{"t":"送昭远兄归陜","f":"五言律诗","c":["种种亲头白，帝城难少留。","倚门应有望，列鼎本无求。","清夜多归梦，红尘厌久游。","此行殊捧檄，辕下五骅骝。"]},{"t":"送济川知汉州二首 其二","f":"五言律诗","c":["千骑拥朱轓，青霞昼绣还。","复寻题柱迹，重过弃繻关。","晓栈流云湿，秋湖脱叶殷。","久游今得意，真不愧江山。"]},{"t":"送济川知汉州二首 其一","f":"五言律诗","c":["金马从容乐，问君何所之。","客心彯若梗，亲发皓如丝。","旧学已孤陋，素交仍别离。","执经时有问，使我复从谁。"]},{"t":"送皇甫寺丞知蓝田县","f":"五言律诗","c":["南山三辅剧，百里古诸侯。","谁为弦歌小，不分宵旰忧。","烟横辋川暝，云照武关秋。","安得无羁束，从君一纵游。"]},{"t":"送祖择之","f":"五言律诗","c":["人生荣与辱，百变似浮云。","自有穷通定，徒劳得丧分。","消愁唯有酒，娱意莫如文。","方寸常萧散，其馀何足云。"]},{"t":"送茹屯田知无为军","f":"七言律诗","c":["叠鼓鸣铙迎候新，军牙孑孑倚淮津。","聊应衣绣过乡曲，不作引章惊故人。","荻迸短芽淝水暖，荷浮圆叶漅湖春。","使君此去荣多少，犹是当年书剑身。"]},{"t":"送赵殿丞归成都","f":"五言律诗","c":["蜀栈锦衣来，高堂绶笥开。","恩辉同日至，喜色共春回。","驷马过邻社，朝裾捧寿杯。","吾生无此乐，空使寸心摧。"]},{"t":"送晁校理知怀州","f":"七言律诗","c":["鸡犬相闻桑柘春，风光明润帝乡邻。","群峰斜转太行角，万谷同趋马颊津。","簪组倾都邀别袂，壶浆满路候行尘。","非君厌薄承明直，天子方今重治人。"]},{"t":"送晁秘丞通判雄州","f":"五言律诗","c":["少傅名德重，蔚然人物师。","群孙满丹穴，嘉瑞尽长离。","勿叹毛羽短，已惊文采奇。","勉哉勤志业，馀庆未应衰。"]},{"t":"送聂秘丞宰桐城二首 其二","f":"五言律诗","c":["七载一相见，恍然如路衢。","形骸渐枯槁，志业转荒芜。","往事云过眼，新愁雪染须。","明朝又分首，上马即重湖。"]},{"t":"送聂秘丞宰桐城二首 其一","f":"五言律诗","c":["问子青云器，胡为不少留。","未能充禄养，安散及身谋。","卓尔千人俊，居然百里忧。","连城价终在，自是玉工羞。"]},{"t":"送致仕朱郎中令孙","f":"七言律诗","c":["世间荣利无穷物，奔走劳劳何所之。","仕宦为郎非不达，功名有命待无时。","橐中虽乏千金直，膝下常携两绶儿。","细校人生能此少，好从闾里乐期颐。"]},{"t":"送惠思归钱塘","f":"五言律诗","c":["孤岫平湖外，禅房老柏阴。","倦游谙浊世，独往遂初心。","夜雨灯窗迥，秋苔屐齿深。","勿锄山径草，便有俗人寻。"]},{"t":"送程端明知成都","f":"五言律诗","c":["高阳将幕开，濯锦使旌来。","欲识关头雪，正如江上梅。","宵衣矜远俗，露冕寄良才。","岂待三年最，脩梧茂帝台。"]},{"t":"送谢都官知光化军","f":"五言律诗","c":["厩吏整车马，匆匆办晓装。","青緺出阊阖，朱旆指沧浪。","野店杏初发，津亭柳已黄。","行行不可驻，犹及劝耕桑。"]},{"t":"送韩太祝知钱塘","f":"五言律诗","c":["冠佩郁相映，由来积德家。","一时推隽异，四海走声华。","图籍添舟重，江山忘路赊。","夷涂指霄汉，局骥不须嗟。"]},{"t":"送蒲中舍霜致政归蜀 其一","f":"五言律诗","c":["厌苦折腰久，飘然黄鹄飞。","田园未芜没，邻曲有光辉。","昔奋儒衣去，今纡朝绂归。","人生贵知足，得此已为稀。"]},{"t":"送蒲中舍霜致政归蜀 其二","f":"五言律诗","c":["念昔两髦日，乌奴同燕游。","随时自有乐，何物可为愁。","岂意今头白，相逢欲涕流。","凭君访题壁，好在水西楼。"]},{"t":"送雷章秘丞知芮城","f":"五言律诗","c":["西伯昔断讼，令名存迄今。","南临大河曲，北倚首阳岑。","俗被圣贤化，人多礼让心。","夫君老经术，终日想鸣琴。"]},{"t":"送僧归吴","f":"五言律诗","c":["高枕聊成梦，晴空忽见花。","浮生尽是客，何处得为家。","旅食帝城久，归舟泽国赊。","勿因菰菜味，回首浩无涯。"]},{"t":"京送僧聪归蜀","f":"五言律诗","c":["翠柏老精舍，红尘倦帝城。","千山一锡远，万里片云轻。","江栈纡还直，天星纵复横。","听猿应更喜，还是故乡声。"]},{"t":"送裴中舍赴太原幕府","f":"五言律诗","c":["元戎台鼎旧，大府节旄新。","边候正无事，宾筵况得人。","山寒太行晓，水碧晋祠春。","斋酿蒲萄熟，飞觞不厌频。"]},{"t":"送燕谏议知潭州","f":"五言律诗","c":["长沙地饶美，贾谊独伤悲。","自古临荣辱，几人无怨咨。","使君拥符节，大舰出江湄。","意气陶然乐，应无吊屈辞。"]},{"t":"送薛水部十丈通判并州","f":"五言律诗","c":["十万貔貅士，旌旗晋水阳。","元戎倚耆硕，别乘选才良。","秀直寒松节，精明利剑铓。","知君留滞久，从此欲腾骧。"]},{"t":"送瀛州签判苏秘丞","f":"五言律诗","c":["高阳十万兵，幕府藉时英。","塞上风犹劲，关南春未生。","投壶边柝静，倚马檄书成。","不忘尘中客，征鸿可寄声。"]},{"t":"送稻醴与子才","f":"五言律诗","c":["昔贤尊道谊，置醴待嘉宾。","今我乐闲放，提壶饷故人。","蚁浮杯面白，味撇瓮头醇。","何以助高兴，篱边菊蕊新。"]},{"t":"重过华下","f":"五言律诗","c":["昔辞莲幕去，三十四炎凉。","旧物三峰雪，新悲一镊霜。","云低秦野阔，木落渭川长。","欲问当时事，无人独叹伤。"]},{"t":"闻龚伯建下第","f":"五言律诗","c":["文章真长物，堪叹又遗贤。","利器空埋土，灵光久照天。","赵锥犹未出，荆璧会须传。","道在虽穷困，知君不慨然。"]},{"t":"首夏二章呈诸邻 其一","f":"五言律诗","c":["首夏木阴薄，清和自一时。","笋抽八九尺，荷生三四枝。","新服裁蝉翼，旧扇拂蛛丝。","莎径热未剧，晨昏往来宜。"]},{"t":"哭马承之","f":"五言律诗","c":["平生千里别，书问亦常来。","隼拂秋云击，鸾兼霏雾回。","向无高世艺，安见出伦才。","有纸盈箱箧，扃封不忍开。"]},{"t":"哭刘仲原 其一","f":"五言律诗","c":["天下才无几，夫君独患多。","高文粲列宿，英辩泻长河。","荣宦成朝梦，浮生度尺波。","旧僚空执酒，相与泪滂沱。"]},{"t":"哭刘仲原 其二","f":"五言律诗","c":["昔醉金明渚，今来慧辩祠。","当年笑相视，此日哭殊悲。","天迥川原净，风高草木衰。","江梅灵气在，泉下复相知。"]},{"t":"哭尚颍","f":"五言律诗","c":["操业五常备，艰难六极全。","仲尼难语命，禆灶不知天。","弱女飘何许，遗文散莫传。","官轻史不录，后世孰称贤。"]},{"t":"夏日","f":"五言律诗","c":["穷边已深夏，气色耿清秋。","鲜旭开山郭，凉烟澹戍楼。","兜铃烽火息，区脱虏尘收。","迨此军中暇，无妨文雅游。"]},{"t":"射堋","f":"五言律诗","c":["叠鼓花前急，红旌竹外高。","惊飙分白羽，馀响振乌号。","壮观倾春陌，欢声涌夜涛。","因兹刑礼俗，岂独事游遨。"]},{"t":"旅宿睢阳南湖","f":"五言律诗","c":["梁王弃宫馆，时世古今违。","犹有南湖水，春来雁鹜飞。","楼台沈倒影，林薄挂馀晖。","豪侈终何在，行人得暂依。"]},{"t":"晋阳三月未有春色","f":"五言律诗","c":["天心均煦妪，物态异芬芳。","上国花应烂，边城柳未黄。","清明空改火，元已漫浮觞。","仍说秋寒早，年年八月霜。"]},{"t":"晓思","f":"五言律诗","c":["束带朝尚早，蓬门未脱扃。","短篱潜落月，老树带孤星。","隐几貂裘黑，开编竹简青。","子云非执戟，何以得穷经。"]},{"t":"朔会堂","f":"五言律诗","c":["朔旦集俺吏，兹堂簪组繁。","舞空孤鹤下，映日两凫翻。","花散东方骑，萍浮北海樽。","须知太守贵，铙吹引朱轮。"]},{"t":"浮醳亭","f":"五言律诗","c":["曲水华榱下，浮觞去复还。","浪摇花影碎，日射酒缸殷。","灭没遥寻客，徘徊怯度湾。","穷欢不知醉，清泚照心颜。"]},{"t":"留别友生","f":"五言律诗","c":["野际共为别，客亭芳草新。","何心更执酒，满目尽伤春。","今古无穷路，东西相背尘。","行行复回首，不欲着鞭频。"]},{"t":"留别逢吉","f":"七言律诗","c":["君念承明臭味稀，相逢惜别重依依。","会稽太守方坐啸，东郭先生还步归。","乐饮林塘留节物，饯行里舍动光辉。","双旌回去行人发，一带长皋烟雨微。"]}]};